import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc, setDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, MessageSquare, Search, X, FileText, UserCheck, 
  ArrowRightLeft, Fingerprint, Send, Archive, Eye, 
  Printer, Folder, File, Download, Plus, ChevronRight,
  UploadCloud, FolderPlus, MoreVertical, CheckCircle2, ShieldCheck,
  AlertTriangle, Home, CornerUpLeft, Paperclip, Save, Timer, MessageCircle,
  Phone, UserX, Edit3, Ban, Check, RefreshCw, Award, Clock, Trash2, FolderInput,
  Move, ThumbsUp, ThumbsDown, ExternalLink, LifeBuoy, ChevronDown
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';
import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'certificado' | 'historico' | 'transferencia' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;

  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(
                 `<iframe width='100%' height='100%' src='${file.url}'></iframe>`
             );
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }
  window.open(file.url, '_blank');
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        try {
            const byteString = atob(url.split(',')[1]);
            const mimeString = url.split(',')[0].split(':')[1].split(';')[0];
            const ab = new ArrayBuffer(byteString.length);
            const ia = new Uint8Array(ab);
            for (let i = 0; i < byteString.length; i++) { ia[i] = byteString.charCodeAt(i); }
            const blob = new Blob([ab], {type: mimeString});
            const blobUrl = URL.createObjectURL(blob);
            const win = window.open(blobUrl, '_blank');
            if (!win) { alert("Pop-up bloqueado. Permita pop-ups para ver o anexo."); }
        } catch (e) { console.error("Erro ao abrir anexo:", e); alert("Erro ao abrir anexo."); }
        return;
    }
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado' | 'arquivado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [chatFilter, setChatFilter] = useState<'abertos'|'fechados'>('abertos');

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);
  const [schoolConfig, setSchoolConfig] = useState<any>({});

  // File Explorer & Save States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false);

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  // Timer & Survey
  const [timerDisplay, setTimerDisplay] = useState<string>('');
  const [survey, setSurvey] = useState({ demandMet: null as boolean|null, problemSolved: null as boolean|null, likedChat: null as boolean|null, rating: 0 });

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Listeners
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Config & Signatures
    getDoc(doc(db, 'system_settings', 'main_config')).then(d => { if(d.exists()) setSchoolConfig(d.data().schoolConfig || {}); });
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  // Timer Logic
  useEffect(() => {
    let interval: any;
    if (activeTicket && activeTicket.status === 'Pendente' && !activeTicket.specialistJoined) {
        interval = setInterval(async () => {
            const now = Date.now();
            const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : Date.now();
            const diff = now - created;
            const limit = 5 * 60 * 1000;
            if (diff >= limit) {
                const hasTimeoutMsg = messages.some((m: any) => m.text.includes("todos os atendentes e especialistas estão ocupados"));
                if (!hasTimeoutMsg) {
                    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                        text: "Infelizmente, todos os atendentes e especialistas estão ocupados no momento. Sua solicitação foi registrada e entraremos em contato através do seu WhatsApp cadastrado em breve.",
                        sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
                    });
                    await updateDoc(doc(db, 'tickets', activeTicket.id), {
                        status: 'Encaminhado', lastMessage: "Encaminhado para WhatsApp (Timeout)", updatedAt: serverTimestamp()
                    });
                }
                setTimerDisplay("Tempo esgotado");
            } else {
                const remaining = Math.ceil((limit - diff) / 1000);
                const mins = Math.floor(remaining / 60);
                const secs = remaining % 60;
                setTimerDisplay(`${mins}:${secs.toString().padStart(2, '0')}`);
            }
        }, 1000);
    } else { setTimerDisplay(''); }
    return () => clearInterval(interval);
  }, [activeTicket, messages]);

  // --- FILE EXPLORER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);
  const handleCreateFolder = async () => { const name = prompt("Nome da nova pasta:"); if (!name) return; await addDoc(collection(db, 'secretaria_arquivos'), { name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid }); };
  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async (ev) => { if (ev.target?.result) { await addDoc(collection(db, 'secretaria_arquivos'), { name: file.name, type: 'file', mimeType: file.type, url: ev.target.result, parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid }); } }; reader.readAsDataURL(file); };
  const handleMoveFile = async () => { if (!fileToMove) return; await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), { parentId: moveTargetFolderId, updatedAt: serverTimestamp() }); setMoveModalOpen(false); setFileToMove(null); alert("Arquivo movido."); };
  const handleNavigate = (folder: any) => { setCurrentFolderId(folder.id); setFolderPath([...folderPath, { id: folder.id, name: folder.name }]); };
  const handleBreadcrumb = (index: number) => { const newPath = folderPath.slice(0, index + 1); setFolderPath(newPath); setCurrentFolderId(newPath[newPath.length - 1].id); };

  // --- CHAT FUNCTIONS ---
  const createTicket = async () => { const docRef = await addDoc(collection(db, 'tickets'), { user: user.displayName, senderId: user.uid, protocolo: Math.random().toString(36).substr(2, 9).toUpperCase(), lastMessage: 'Atendimento Iniciado', status: 'Pendente', createdAt: serverTimestamp(), updatedAt: serverTimestamp() }); await addDoc(collection(db, 'tickets', docRef.id, 'messages'), { text: `Olá ${user.displayName?.split(' ')[0]}. Assistente virtual iniciado.`, sender: 'Sistema', isBot: true, options: ['Problemas de Acesso', 'Material Didático', 'Aplicativo / Perfil', 'Elogio / Sugestão', 'Reclamação'], createdAt: serverTimestamp() }); const snap = await getDoc(docRef); if (snap.exists()) setActiveTicket({ id: snap.id, ...snap.data() }); };
  const handleBotOption = async (option: string) => { if(!activeTicket) return; await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: option, sender: 'Aluno', createdAt: serverTimestamp() }); let resp = 'Aguarde um atendente.'; let opts: string[]=[]; if(option.includes('Problemas')) opts=['Sim, resolvido', 'Não']; await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: resp, sender: 'Sistema', isBot: true, options: opts.length?opts:undefined, createdAt: serverTimestamp() }); await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: `Bot: ${option}`, updatedAt: serverTimestamp() }); };
  const sendMessage = async () => { if (!chatMessage.trim() || !activeTicket) return; await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Secretaria', createdAt: serverTimestamp() }); await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp(), status: 'Em Atendimento', specialistJoined: true }); setChatMessage(''); };
  const handleChatFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if(!file || !activeTicket) return; const reader = new FileReader(); reader.onload = async (ev) => { if(ev.target?.result) await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: `Anexo: ${file.name}`, attachmentUrl: ev.target.result as string, sender: 'Secretaria', createdAt: serverTimestamp() }); }; reader.readAsDataURL(file); };
  const handleStudentFinalize = async () => { if(!activeTicket) return; if(confirm("Encerrar atendimento?")) await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Finalizado', updatedAt: serverTimestamp() }); setActiveTicket(null); };

  // --- PDF GENERATOR (UPDATED FOR LANDSCAPE CERTIFICATE) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          const isCertificate = docType === 'conclusao';
          const docPdf = new jsPDF({
              orientation: isCertificate ? 'landscape' : 'portrait',
              unit: 'mm',
              format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();

          // --- CERTIFICADO DESIGN (2 Pages, Landscape) ---
          if (isCertificate) {
              // PAGE 1: FRONT
              // Ornamental Border
              docPdf.setDrawColor(20, 20, 50); // Dark Blue/Black
              docPdf.setLineWidth(3);
              docPdf.rect(10, 10, width - 20, height - 20); // Outer
              docPdf.setLineWidth(0.5);
              docPdf.rect(13, 13, width - 26, height - 26); // Inner

              // HEADER: Logo Left, School Name Right (Centered vertically)
              const headerY = 40;
              const logoSize = 35;
              let logoWidth = 0;

              if (schoolConfig.logoUrl) {
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', 30, 25, logoSize, logoSize);
                  logoWidth = logoSize + 10;
              }

              // School Info Text (Right of Logo)
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(24);
              docPdf.setTextColor(20, 20, 60);
              docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", 30 + logoWidth, 35);

              docPdf.setFontSize(10);
              docPdf.setFont("helvetica", "normal");
              docPdf.setTextColor(80);
              docPdf.text(`CNPJ: ${schoolConfig.cnpj || '00.000.000/0001-00'} | Portaria MEC nº 1004/2017`, 30 + logoWidth, 42);
              docPdf.text("Credenciamento Nacional em Teologia e Ciências Humanas", 30 + logoWidth, 47);

              // BODY
              let y = 85;
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(48);
              docPdf.setTextColor(0);
              docPdf.text("CERTIFICADO", width / 2, y, { align: "center" });

              y += 25;
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(16);
              docPdf.setTextColor(40);

              const margin = 40;
              const textWidth = width - (margin * 2);

              const certText = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome?.toUpperCase() || 'TEOLOGIA'}, cumprindo integralmente a carga horária exigida e obtendo a aprovação necessária para a outorga deste título.`;

              const splitCertText = docPdf.splitTextToSize(certText, textWidth);
              docPdf.text(splitCertText, width / 2, y, { align: "center" });

              y += 35;
              const dataEmissao = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              docPdf.setFontSize(12);
              docPdf.text(dataEmissao, width - 50, y, { align: "right" });

              // SIGNATURES
              const sigY = height - 45; 
              const sigLineW = 60;

              // 3 Columns of signatures
              const col1 = margin + 10;
              const col2 = (width / 2) - (sigLineW / 2);
              const col3 = width - margin - 10 - sigLineW;

              docPdf.setDrawColor(0);
              docPdf.setLineWidth(0.5);

              // Director
              docPdf.line(col1, sigY, col1 + sigLineW, sigY);
              if(directorSignature) docPdf.addImage(directorSignature, 'PNG', col1 + 5, sigY - 15, 50, 15);
              docPdf.setFontSize(9);
              docPdf.text("Diretor Executivo", col1 + (sigLineW/2), sigY + 5, { align: "center" });

              // Instructor
              docPdf.line(col2, sigY, col2 + sigLineW, sigY);
              docPdf.text("Instrutor Titular", col2 + (sigLineW/2), sigY + 5, { align: "center" });

              // Secretary
              docPdf.line(col3, sigY, col3 + sigLineW, sigY);
              if(secSignature) docPdf.addImage(secSignature, 'PNG', col3 + 5, sigY - 15, 50, 15);
              docPdf.text("Secretaria Geral", col3 + (sigLineW/2), sigY + 5, { align: "center" });

              // Authenticity Key (No QR on Front)
              docPdf.setFontSize(7);
              docPdf.setTextColor(150);
              docPdf.text(`Chave de Autenticidade: ${code}`, width / 2, height - 15, { align: "center" });

              // PAGE 2: BACK (Histórico / Transcript)
              docPdf.addPage('a4', 'landscape');

              // Header Block (Top Box)
              docPdf.setDrawColor(200);
              docPdf.setFillColor(245, 245, 245);
              docPdf.rect(15, 15, width - 30, 30, 'F');

              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(14);
              docPdf.setTextColor(0);
              docPdf.text("HISTÓRICO ESCOLAR", 20, 25);

              docPdf.setFontSize(10);
              docPdf.setFont("helvetica", "normal");
              docPdf.text(`ALUNO: ${opStudent.displayName?.toUpperCase()}`, 20, 33);
              docPdf.text(`CURSO: ${courseData.nome?.toUpperCase()}`, 20, 40);

              docPdf.text(`RA: ${opStudent.academicId}`, width/2, 33);
              docPdf.text(`CPF: ${opStudent.cpf}`, width/2, 40);

              docPdf.text(`Portaria: 1004/2017`, width - 60, 33);
              docPdf.text(`Lei nº 9.394/96`, width - 60, 40);

              // Table Generation
              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo Indefinido",
                  "40h", // Default workload
                  "100%", // Default Attendance for certificate
                  "10.0", // Default Grade for certificate
                  courseData.professorResponsavel || "Corpo Docente",
                  "Mestre" // Default Title
              ]);

              // Calculate Total Hours
              const totalHours = modulesData.length * 40;
              tableBody.push(["CARGA HORÁRIA TOTAL", `${totalHours}h`, "-", "-", "-", "-"]);

              autoTable(docPdf, {
                  startY: 55,
                  head: [['Disciplina / Conteúdo Programático', 'C.H.', 'Frequência', 'Nota Final', 'Docente Responsável', 'Titulação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [40, 40, 60], halign: 'center', fontSize: 9, fontStyle: 'bold' },
                  bodyStyles: { halign: 'center', fontSize: 8 },
                  columnStyles: { 0: { halign: 'left', cellWidth: 80 } }, // Wider column for Discipline
                  margin: { left: 15, right: 15 }
              });

              // Bottom Info (Verification)
              const footerY = height - 35;

              // QR Code
              docPdf.addImage(qrCodeDataUrl, 'PNG', 15, footerY, 25, 25);

              // Verification Text
              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(9);
              docPdf.setTextColor(0);
              docPdf.text("VALIDAÇÃO DIGITAL", 45, footerY + 8);

              docPdf.setFont("helvetica", "normal");
              docPdf.setFontSize(8);
              docPdf.setTextColor(60);
              docPdf.text(`Acesse: ${window.location.origin}/verify`, 45, footerY + 13);
              docPdf.text(`Chave Única: ${code}`, 45, footerY + 18);
              docPdf.text("Documento emitido eletronicamente conforme MP 2.200-2/2001.", 45, footerY + 23);

          } else {
              // --- STANDARD DOCUMENTS (Portrait) ---
              // Existing logic maintained, just ensuring QR Code

              // Header
              if (schoolConfig.logoUrl) {
                  const logoSize = 25;
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', (width/2) - (logoSize/2), 20, logoSize, logoSize);
              }
              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(16);
              docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", width/2, 55, {align:'center'});

              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(18);
              docPdf.text(docTitle, width / 2, 80, { align: "center" });

              // Content
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(12);
              const margin = 25;
              let y = 100;

              const bodyText = docType === 'matricula' 
                  ? `Declaramos que ${opStudent.displayName}, CPF ${opStudent.cpf}, está regularmente MATRICULADO(A) no curso de ${courseData.nome}.`
                  : docType === 'transferencia' 
                  ? `Declaramos que ${opStudent.displayName}, CPF ${opStudent.cpf}, solicitou transferência nesta data.`
                  : `Histórico Escolar de ${opStudent.displayName}.`; // Fallback for simple historic

              const splitBody = docPdf.splitTextToSize(bodyText, width - (margin*2));
              docPdf.text(splitBody, margin, y);

              if(docType === 'historico') {
                   // Simple portrait table
                   const tableBody = modulesData.map((m: any) => [m.title, "Aprovado"]);
                   autoTable(docPdf, {
                      startY: y + 20,
                      head: [['Disciplina', 'Situação']],
                      body: tableBody,
                      theme: 'grid',
                      margin: { left: margin, right: margin }
                   });
              }

              // Date
              y = height - 80;
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR')}.`;
              docPdf.text(dateStr, width - margin, y, { align: "right" });

              // Signatures
              const sigY = height - 50;
              if(directorSignature) docPdf.addImage(directorSignature, 'PNG', margin, sigY - 15, 40, 15);
              docPdf.line(margin, sigY, margin + 60, sigY);
              docPdf.setFontSize(8);
              docPdf.text("Diretor", margin + 30, sigY + 5, {align:'center'});

              if(secSignature) docPdf.addImage(secSignature, 'PNG', width - margin - 60, sigY - 15, 40, 15);
              docPdf.line(width - margin - 60, sigY, width - margin, sigY);
              docPdf.text("Secretária", width - margin - 30, sigY + 5, {align:'center'});

              // Footer with QR Code
              const qrY = height - 30;
              docPdf.addImage(qrCodeDataUrl, 'PNG', margin, qrY, 20, 20);
              docPdf.text(`Validação: ${code}`, margin + 25, qrY + 10);
          }

          const pdfBase64 = docPdf.output('datauristring');
          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId }, courseData, modulesData }
          });

          const blob = docPdf.output('blob');
          const blobUrl = URL.createObjectURL(blob);
          window.open(blobUrl, '_blank');
          alert("Documento gerado com sucesso!");

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro ao gerar: " + e.message);
      } finally { setIsGeneratingPdf(false); }
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
