                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
