      doc.setTextColor(0);

      doc.text(`Nome Civil: ${student.displayName?.toUpperCase()}`, margin + 5, startY + 12);
      doc.text(`Curso: ${student.cursoInicial || 'TEOLOGIA BÁSICA'}`, margin + 100, startY + 12);

      doc.text(`CPF: ${student.cpf || '000.000.000-00'}`, margin + 5, startY + 18);
      doc.text(`Matrícula (RA): ${student.academicId || '---'}`, margin + 100, startY + 18);

      return startY + boxHeight + 15;
  };

  // --- PDF GENERATOR ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const isLandscape = docType === 'conclusao';

          const titles = {
            matricula: 'DECLARAÇÃO DE MATRÍCULA',
            conclusao: 'CERTIFICADO',
            historico: 'HISTÓRICO ESCOLAR',
            transferencia: 'GUIA DE TRANSFERÊNCIA'
          };
          const docTitle = titles[docType];

          let modulesData: any[] = [];
          let courseData: any = {};

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data());
          }
          if(modulesData.length === 0) {
             modulesData = [
                 { title: 'Teologia Sistemática I', hours: 40, grade: 10.0 },
                 { title: 'Hermenêutica Bíblica', hours: 30, grade: 9.5 },
                 { title: 'História da Igreja', hours: 50, grade: 10.0 },
                 { title: 'Exegese do Novo Testamento', hours: 40, grade: 9.0 },
             ];
          }

          const validationUrl = `${window.location.origin}/verify?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          const docPdf = new jsPDF({
              orientation: isLandscape ? 'landscape' : 'portrait',
              unit: 'mm', format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();
          const margin = 20;

          if (docType === 'conclusao') {
              // --- CERTIFICADO (LANDSCAPE, 2 PAGES) ---

              // Page 1: Front
              drawPageBorder(docPdf, 'l');

              // Logo
              if (schoolConfig.logoUrl) {
                  const logoSize = 30;
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', (width/2) - (logoSize/2), 20, logoSize, logoSize);
              }

              // Title
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(36);
              docPdf.setTextColor(30, 41, 59);
              docPdf.text("CERTIFICADO", width / 2, 65, { align: "center" });

              // Body
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(14);
              docPdf.setTextColor(0);
              const text = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '000.000.000-00'}, concluiu com êxito o curso de ${opStudent.cursoInicial?.toUpperCase() || 'TEOLOGIA AVANÇADA'}, cumprindo integralmente a carga horária exigida e obtendo a aprovação necessária para a outorga deste título.`;
              const textLines = docPdf.splitTextToSize(text, width - 100);
              docPdf.text(textLines, width / 2, 90, { align: "center" });

              // Date
              docPdf.setFontSize(12);
              docPdf.text(formatDateLong(), width - 50, 130, { align: "right" });

              // Signatures
              const sigY = 160;
              docPdf.setLineWidth(0.5);

              docPdf.line(60, sigY, 120, sigY);
              if (directorSignature) docPdf.addImage(directorSignature, 'PNG', 70, sigY - 25, 40, 20);
              docPdf.setFontSize(10);
              docPdf.text("Diretor Acadêmico", 90, sigY + 5, { align: "center" });

              docPdf.line(width - 120, sigY, width - 60, sigY);
              if (secSignature) docPdf.addImage(secSignature, 'PNG', width - 110, sigY - 25, 40, 20);
              docPdf.text("Secretaria Geral", width - 90, sigY + 5, { align: "center" });

              // Verification
              docPdf.setFontSize(7);
              docPdf.setTextColor(150);
              docPdf.text(`Chave de Autenticidade: ${code}`, width / 2, height - 15, { align: "center" });

              // Page 2: Back (Transcript)
              docPdf.addPage('a4', 'landscape');
              drawPageBorder(docPdf, 'l');

              // Header Back
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(16);
              docPdf.setTextColor(0);
              docPdf.text("HISTÓRICO ESCOLAR", width / 2, 30, { align: "center" });

              // Info Box
              drawStudentInfoBox(docPdf, opStudent, 40, width, margin);

              // Table
              const tableBody = modulesData.map((m: any) => [
                  m.title || "Disciplina", 
                  (m.hours || 40) + 'h', 
                  (m.grade || 10.0).toFixed(1), 
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: 75,
                  head: [['Disciplina / Módulo', 'Carga Horária', 'Nota Final', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [30, 41, 59], halign: 'center' },
                  columnStyles: {
                      0: { cellWidth: 'auto' },
                      1: { halign: 'center', cellWidth: 30 },
                      2: { halign: 'center', cellWidth: 30 },
                      3: { halign: 'center', cellWidth: 40 }
                  },
                  styles: { fontSize: 10, cellPadding: 2 },
                  margin: { left: margin, right: margin }
              });

              // QR Footer
              docPdf.addImage(qrCodeDataUrl, 'PNG', margin, height - 35, 20, 20);
              docPdf.setFontSize(8);
              docPdf.text("VALIDAÇÃO DIGITAL", margin + 25, height - 28);
              docPdf.text(`Código: ${code}`, margin + 25, height - 23);
              docPdf.text(`URL: ${validationUrl}`, margin + 25, height - 18);

          } else {
              // --- OTHER DOCUMENTS (PORTRAIT, NO SIGNATURES/BODY) ---
              drawPageBorder(docPdf, 'p');

              // Header
              let cursorY = 25;
              if (schoolConfig.logoUrl) {
                  const logoSize = 20;
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', (width/2) - (logoSize/2), 15, logoSize, logoSize);
                  cursorY = 40;
              }
              cursorY = drawHeader(docPdf, width, cursorY, docTitle);

              // Student Info
              cursorY = drawStudentInfoBox(docPdf, opStudent, cursorY, width, margin);

              // Specific Content (Table only for Historic)
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(12);

              if (docType === 'historico') {
                  const tableBody = modulesData.map((m: any) => [
                      m.title || "Módulo Curricular", 
                      (m.hours || 40) + 'h', 
                      "100%", 
                      (m.grade || 10.0).toFixed(1), 
                      "Aprovado"
                  ]);

                  autoTable(docPdf, {
                      startY: cursorY,
                      head: [['Disciplina', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'striped',
                      headStyles: { fillColor: [30, 41, 59] },
                      styles: { fontSize: 10, cellPadding: 3 },
                      margin: { left: margin, right: margin }
                  });
                  cursorY = (docPdf as any).lastAutoTable.finalY + 20;
              } else {
                  // For Transfer/Matricula: No body text, no table. Just space.
                  cursorY += 20;
              }

              // Date
              if (cursorY > height - 60) {
                  docPdf.addPage();
                  drawPageBorder(docPdf, 'p');
                  cursorY = 40;
              }

              docPdf.setFont("times", "italic");
              docPdf.text(formatDateLong(), width - margin, cursorY, { align: "right" });

              // Footer (QR Code only, NO Signatures)
              const qrY = height - 40;
              docPdf.addImage(qrCodeDataUrl, 'PNG', margin, qrY, 25, 25);
              docPdf.setFontSize(8);
              docPdf.setFont("helvetica", "bold");
              docPdf.text("AUTENTICIDADE DIGITAL", margin + 30, qrY + 8);
              docPdf.setFont("helvetica", "normal");
              docPdf.text(`Hash: ${code}`, margin + 30, qrY + 13);
              docPdf.text(`Valide em: ${validationUrl}`, margin + 30, qrY + 18);
          }

          const pdfBase64 = docPdf.output('datauristring');
          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId }, courseData, modulesData }
          });

          const blob = docPdf.output('blob');
          const blobUrl = URL.createObjectURL(blob);
          window.open(blobUrl, '_blank');
          alert("Documento gerado com sucesso!");

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro ao gerar: " + e.message);
      } finally { setIsGeneratingPdf(false); }
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
          alert('Dados do aluno atualizados.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao salvar: ' + e.message);
      }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              status: 'ativo',
              updatedAt: serverTimestamp()
          });
          alert('Matrícula validada com sucesso.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao validar: ' + e.message);
      }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      {/* HEADER */}
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">
         {/* TAB: LISTA DE ATENDIMENTOS */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-4 bg-slate-50 border-b flex gap-2">
                    {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                        <button key={f} onClick={() => setTicketFilter(f)} className={`px-3 py-1 rounded text-[10px] font-black uppercase ${ticketFilter === f ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>{f}</button>
                    ))}
                </div>
                <div className="flex-1 overflow-y-auto p-4">
                    {tickets.filter(t => ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter).map(t => (
                        <div key={t.id} className="flex justify-between p-3 border-b hover:bg-slate-50 items-center">
                            <div>
                                <span className="font-bold text-xs text-indigo-700">#{t.protocolo}</span> 
                                <span className="text-xs ml-2 text-slate-700">{t.user}</span>
                                <div className="text-[10px] text-slate-400">{t.lastMessage}</div>
                            </div>
                            <button onClick={() => {setActiveTicket(t); setActiveTab('chat');}} className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded text-[10px] font-bold uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">Abrir</button>
                        </div>
                    ))}
                    {tickets.length === 0 && <div className="text-center p-10 text-slate-400 text-sm">Nenhum atendimento encontrado.</div>}
                </div>
             </div>
         )}

         {/* TAB: CHAT */}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative">
                {activeTicket ? (
                  <>
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                       <div><h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Status: {activeTicket.status}</p></div>
                       {timerDisplay && <div className="flex items-center gap-2 px-3 py-1 bg-amber-50 text-amber-600 rounded-lg border border-amber-100 animate-pulse"><Clock size={12} /><span className="text-[10px] font-black uppercase">Espera: {timerDisplay}</span></div>}
                       <div className="flex gap-2">
                           {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' && <button onClick={handleStudentFinalize} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all">Encerrar Atendimento</button>}
                           {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') && <div className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-[9px] font-black uppercase animate-pulse">Pesquisa Pendente</div>}
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' || m.sender === 'Sistema' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[75%] p-3 rounded-2xl text-xs font-medium leading-relaxed shadow-sm 
                                ${m.sender === 'Secretaria' ? 'bg-indigo-600 text-white rounded-br-none' : 
                                  m.isBot ? 'bg-slate-200 text-slate-600 rounded-bl-none text-[11px]' : 
                                  'bg-white border border-slate-200 text-slate-700 rounded-bl-none'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white truncate"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Anexo</span> <ExternalLink size={10}/></div>}
                            </div>
                            {m.sender === 'Sistema' && m.options && activeTicket.status === 'Pendente' && (
                                <div className="mt-2 flex flex-wrap gap-1 justify-end">{m.options.map((opt: string) => <span key={opt} className="px-2 py-1 bg-slate-100 text-slate-400 border border-slate-200 rounded text-[9px]">{opt}</span>)}</div>
                            )}
                            <span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-1">{m.sender}</span>
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') ? (
                        <div className="p-6 bg-slate-100 border-t flex flex-col items-center gap-4 text-center">
                            <h4 className="text-sm font-bold text-slate-700 uppercase">Pesquisa de Satisfação (Cliente)</h4>
                            <div className="text-xs text-slate-500">Aguardando avaliação do aluno ou arquivamento manual.</div>
                            <button onClick={submitSurvey} className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold uppercase text-xs shadow-lg hover:bg-indigo-700">Arquivar Ticket</button>
                        </div>
                    ) : activeTicket.status !== 'Arquivado' ? (
                      <div className="p-4 border-t border-slate-100 bg-white"><div className="flex gap-3 items-center"><button onClick={() => chatFileInputRef.current?.click()} className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-indigo-100 hover:text-indigo-600 transition-all"><Paperclip size={18}/></button><input type="file" ref={chatFileInputRef} className="hidden" onChange={handleChatFileUpload}/><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-slate-50 border-none rounded-lg py-2 px-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Digite sua resposta..." /><button onClick={sendMessage} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-md transition-all"><Send size={18}/></button></div></div>
                    ) : <div className="p-4 text-center bg-slate-50 text-xs text-slate-400 uppercase font-bold">Ticket Arquivado</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-4"><MessageSquare size={48} className="mb-4 opacity-20"/><p className="text-xs uppercase font-bold">Selecione um atendimento</p></div>
                )}
             </div>
         )}

         {/* TAB: ARQUIVOS */}
         {activeTab === 'arquivos' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                 <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                     <div className="flex gap-1 items-center overflow-x-auto">
                        {folderPath.map((folder, idx) => (
                            <div key={folder.id} className="flex items-center">
                                <button onClick={() => handleBreadcrumb(idx)} className="text-xs font-bold text-slate-600 hover:text-indigo-600 uppercase hover:underline">{folder.name}</button>
                                {idx < folderPath.length - 1 && <ChevronRight size={12} className="mx-1 text-slate-300"/>}
                            </div>
                        ))}
                     </div>
                     <div className="flex gap-2">
                        <button onClick={handleCreateFolder} className="p-2 bg-white border border-slate-200 rounded hover:bg-indigo-50 text-indigo-600"><FolderPlus size={16}/></button>
                        <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 shadow-sm"><UploadCloud size={16}/></button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                     </div>
                 </div>
                 <div className="flex-1 overflow-y-auto p-4">
                     <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                        {currentItems.map(item => (
                            <div key={item.id} className="group relative bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center justify-center gap-3 hover:shadow-md hover:border-indigo-200 transition-all cursor-pointer"
                                 onClick={() => item.type === 'folder' ? handleNavigate(item) : viewFile(item)}
                            >
                                {item.type === 'folder' ? <Folder size={32} className="text-indigo-400 group-hover:text-indigo-600"/> : <FileText size={32} className="text-slate-400 group-hover:text-slate-600"/>}
                                <span className="text-[10px] font-bold uppercase text-center text-slate-600 truncate w-full">{item.name}</span>
                                <button onClick={(e) => { e.stopPropagation(); handleDeleteFile(item.id); }} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 p-1 text-rose-400 hover:bg-rose-50 rounded"><Trash2 size={12}/></button>
                                <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="absolute top-1 left-1 opacity-0 group-hover:opacity-100 p-1 text-indigo-400 hover:bg-indigo-50 rounded"><Move size={12}/></button>
                            </div>
                        ))}
                     </div>
                 </div>
             </div>
         )}

         {/* TAB: OPERACIONAL (GERAÇÃO DE DOCS) */}
         {activeTab === 'operacional' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                 <div className="p-6 border-b border-slate-100 bg-slate-50">
                    <h2 className="text-sm font-black uppercase text-slate-800 mb-4 flex items-center gap-2"><Printer size={16}/> Emissão de Documentos</h2>
                    <div className="flex gap-4">
                        <div className="flex-1 relative">
                            <Search className="absolute left-3 top-3 text-slate-400" size={16}/>
                            <input 
                                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500" 
                                placeholder="Buscar aluno por nome ou CPF..."
                                value={studentSearchTerm}
                                onChange={e => setStudentSearchTerm(e.target.value)}
                            />
                        </div>
                    </div>
                 </div>

                 <div className="flex-1 flex overflow-hidden">
                    {/* Lista de Alunos */}
                    <div className="w-1/3 border-r border-slate-100 overflow-y-auto bg-slate-50/50 p-2">
                        {students.filter(s => s.displayName?.toLowerCase().includes(studentSearchTerm.toLowerCase()) || s.cpf?.includes(studentSearchTerm)).map(s => (
                            <div key={s.uid} onClick={() => setOpStudent(s)} className={`p-3 mb-2 rounded-lg cursor-pointer border ${opStudent?.uid === s.uid ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'}`}>
                                <div className="font-bold text-xs uppercase">{s.displayName}</div>
                                <div className="text-[10px] opacity-70 flex justify-between mt-1">
                                    <span>CPF: {s.cpf || '---'}</span>
                                    <span>{s.academicId}</span>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Painel de Ações */}
                    <div className="flex-1 p-6 overflow-y-auto">
                        {opStudent ? (
                            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
                                <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
                                    <h3 className="font-black text-indigo-900 text-lg uppercase">{opStudent.displayName}</h3>
                                    <div className="grid grid-cols-2 gap-4 mt-2 text-xs text-indigo-700">
                                        <p><strong>Email:</strong> {opStudent.email}</p>
                                        <p><strong>Curso:</strong> {opStudent.cursoInicial || 'Não definido'}</p>
                                        <p><strong>Status:</strong> <span className="px-2 py-0.5 bg-white rounded border border-indigo-200 uppercase font-bold text-[10px]">{opStudent.status || 'Pendente'}</span></p>
                                        <button onClick={() => {setEditingStudent(opStudent); setAuditModalOpen(true);}} className="text-left underline hover:text-indigo-900">Editar Dados / Validar</button>
                                    </div>
                                </div>

                                <div>
                                    <h4 className="text-xs font-bold uppercase text-slate-400 mb-3 tracking-widest">Documentos Disponíveis</h4>
                                    <div className="grid grid-cols-2 gap-4">
                                        {[
                                            {id: 'matricula', label: 'Declaração de Matrícula', icon: FileText},
                                            {id: 'historico', label: 'Histórico Escolar', icon: File},
                                            {id: 'conclusao', label: 'Certificado de Conclusão', icon: Award},
