/**
 * Upload de File para Storage e retorno de { url, storagePath }.
 */
export async function uploadFileToStorage(
  file: File,
  storagePath: string
): Promise<{ url: string; storagePath: string }> {
  const r = ref(storage, storagePath);
  await uploadBytes(r, file);
  const url = await getDownloadURL(r);
  return { url, storagePath };
}

/**
 * Upload de Blob para Storage e retorno de { url, storagePath }.
 */
export async function uploadBlobToStorage(
  blob: Blob,
  storagePath: string,
  contentType?: string
): Promise<{ url: string; storagePath: string }> {
  const r = ref(storage, storagePath);
  await uploadBytes(r, blob, contentType ? { contentType } : undefined);
  const url = await getDownloadURL(r);
  return { url, storagePath };
}

/**
 * Exclui um objeto do Storage pelo storagePath salvo no Firestore.
 */
export async function deleteFromStorage(storagePath?: string | null) {
  if (!storagePath) return;
  const r = ref(storage, storagePath);
  await deleteObject(r);
}

/**
 * Ajuda para nomes seguros em paths (evita caracteres estranhos).
 */
export function safeName(name: string) {
  return name
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w.\-]+/g, "_")
    .slice(0, 120);
}

export async function fetchAsDataURL(url: string): Promise<string> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Falha ao baixar asset: ${url}`);
  const blob = await res.blob();

  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });

  return dataUrl;
}

