  // ✅ Anexo do chat: Storage (não Base64)
  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeTicket) return;

    try {
      const clean = safeName(file.name);
