  serverTimestamp,
  orderBy,
  where,
  deleteDoc,
  getDoc,
  addDoc,
  getDocs,
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

import { db } from "../firebase";
import { User } from "../types";

import {
  MessageSquare,
  Search,
  FileText,
  ArrowRightLeft,
  Send,
  Archive,
  Printer,
  Folder,
  UploadCloud,
  FolderPlus,
  ChevronRight,
  ShieldCheck,
  Clock,
  Trash2,
  Move,
  ExternalLink,
  Paperclip,
  Award,
  File,
  Fingerprint
} from "lucide-react";

import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import SignaturePad from '../components/SignaturePad';

import { fetchAsDataURL } from "../services/pdfAssets";
import {
  deleteFromStorage,
  safeName,
  uploadBlobToStorage,
  uploadFileToStorage,
} from "../services/storageService";

import type { FileItem, StudentUser, Ticket, TicketMessage, TicketStatus } from "../types/secretariat";

interface SecretariatViewProps {
  user: User;
}
type SecretariatTab = "atendimento" | "chat" | "arquivos" | "operacional";
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao' | 'certificado';

// ---- HELPERS ----
const generateVerificationCode = () => {
  const y = new Date().getFullYear();
  const a = Math.random().toString(36).slice(2, 6).toUpperCase();
  const b = Math.random().toString(36).slice(2, 6).toUpperCase();
  return `${y}.${a}.${b}`;
};

const normalizeFilterStatus = (filter: "todos" | "pendente" | "ativo" | "finalizado") => {
  if (filter === "pendente") return "Pendente";
  if (filter === "ativo") return "Ativo";
  if (filter === "finalizado") return "Finalizado";
  return null;
};

const viewFile = (file: FileItem) => {
  if (!file?.url) return;

  const isPdf = file.mimeType === "application/pdf" || file.name?.toLowerCase().endsWith(".pdf");
  if (isPdf) {
    const newWindow = window.open();
    if (newWindow) {
        if (file.url.startsWith('data:')) {
           newWindow.document.write(
               `<iframe width='100%' height='100%' style='border:none;' src='${file.url}'></iframe>`
           );
           newWindow.document.title = file.name;
        } else {
           newWindow.location.href = file.url;
        }
    } else {
        alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
    }
    return;
  }
  window.open(file.url, "_blank");
};

const viewAttachment = (url?: string) => {
  if (!url) return;
  window.open(url, "_blank");
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>("atendimento");
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [students, setStudents] = useState<StudentUser[]>([]);
  const [fileSystem, setFileSystem] = useState<FileItem[]>([]);

  // Atendimento
  const [ticketFilter, setTicketFilter] = useState<"todos" | "pendente" | "ativo" | "finalizado">("todos");
  const [activeTicket, setActiveTicket] = useState<Ticket | null>(null);

  // Chat
  const [messages, setMessages] = useState<TicketMessage[]>([]);
  const [chatMessage, setChatMessage] = useState("");

  // General / Config
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);
  const [schoolConfig, setSchoolConfig] = useState<any>({});
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);

  // File Explorer
  const [currentFolderId, setCurrentFolderId] = useState<string>("root");
  const [folderPath, setFolderPath] = useState<{ id: string; name: string }[]>([{ id: "root", name: "Arquivos" }]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<FileItem | null>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState("root");
  const [attachMode, setAttachMode] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Operacional
  const [opStudent, setOpStudent] = useState<StudentUser | null>(null);
  const [studentSearchTerm, setStudentSearchTerm] = useState("");
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Auditoria
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<StudentUser | null>(null);

  // Timer
  const [timerDisplay, setTimerDisplay] = useState("");
  const timerRef = useRef<number | null>(null);

  // Survey
  const [survey, setSurvey] = useState({ demandMet: null as boolean|null, problemSolved: null as boolean|null, likedChat: null as boolean|null, rating: 0 });

  // ---- LISTENERS GLOBAIS (uma vez) ----
  useEffect(() => {
    // Tickets
    const unsubT = onSnapshot(collection(db, "tickets"), (s) => {
      const t = s.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as Ticket[];
      t.sort((a: any, b: any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
      setTickets(t);

      // Mantém activeTicket atualizado sem recriar listeners
      if (activeTicket?.id) {
        const updated = t.find((x) => x.id === activeTicket.id);
        if (updated) setActiveTicket(updated);
      }
    });

    // Arquivos
    const unsubF = onSnapshot(collection(db, "secretaria_arquivos"), (s) => {
      setFileSystem(s.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as FileItem[]);
    });

    // Alunos
    const unsubS = onSnapshot(collection(db, "users"), (s) => {
      const allUsers = s.docs.map((d) => ({ uid: d.id, ...(d.data() as any) })) as StudentUser[];
      setStudents(allUsers.filter((u) => u.role === "aluno"));
    });

    // Assinaturas
    getDoc(doc(db, "users", user.uid)).then((d) => d.exists() && setSecSignature((d.data() as any).signatureUrl || null));
    const qDir = query(collection(db, "users"), where("role", "==", "diretor"));
    getDocs(qDir).then((s) => {
      if (!s.empty) setDirectorSignature((s.docs[0].data() as any).signatureUrl || null);
    });

    // Config escola
    getDoc(doc(db, "system_settings", "main_config")).then((s) => {
      if (s.exists()) setSchoolConfig((s.data() as any).schoolConfig || {});
    });

    return () => {
      unsubT();
      unsubF();
      unsubS();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user.uid]);

  // ---- CHAT SYNC (por ticket) ----
  useEffect(() => {
    if (!activeTicket) {
      setMessages([]);
      return;
    }
    const q = query(collection(db, "tickets", activeTicket.id, "messages"), orderBy("createdAt", "asc"));
    return onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as TicketMessage[];
      setMessages(list);
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: "smooth" }), 80);
    });
  }, [activeTicket?.id]);

  // ---- TIMER: só depende do id + status ----
  useEffect(() => {
    if (timerRef.current) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setTimerDisplay("");

    if (!activeTicket || activeTicket.status !== "Pendente") return;

    timerRef.current = window.setInterval(async () => {
      try {
        const now = Date.now();
        const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : now;
        const diff = now - created;
        const limit = 5 * 60 * 1000;

        if (diff >= limit) {
          // evita spam: confere no estado atual de messages
          const hasTimeoutMsg = messages.some((m) => (m.text || "").includes("todos os atendentes"));
          if (!hasTimeoutMsg && activeTicket?.id) {
            await addDoc(collection(db, "tickets", activeTicket.id, "messages"), {
              text: "Infelizmente, todos os atendentes estão ocupados. Sua solicitação foi registrada e entraremos em contato.",
              sender: "Sistema",
              isBot: true,
              createdAt: serverTimestamp(),
            });
            await updateDoc(doc(db, "tickets", activeTicket.id), {
              status: "Encaminhado",
              lastMessage: "Timeout - Encaminhado",
              updatedAt: serverTimestamp(),
            });
          }
          setTimerDisplay("Tempo esgotado");
        } else {
          const remaining = Math.ceil((limit - diff) / 1000);
          const mins = Math.floor(remaining / 60);
          const secs = remaining % 60;
          setTimerDisplay(`${mins}:${secs.toString().padStart(2, "0")}`);
        }
      } catch {
        // silencioso (evita travar UI)
      }
    }, 1000);

    return () => {
      if (timerRef.current) window.clearInterval(timerRef.current);
      timerRef.current = null;
    };
  }, [activeTicket?.id, activeTicket?.status, activeTicket?.createdAt, messages, activeTicket]);

  // ---- FILE EXPLORER ----
  const getFilesForFolder = (folderId: string) => {
    return fileSystem
      .filter((f) => f.parentId === folderId)
      .sort((a, b) => {
        if (a.type === b.type) return a.name.localeCompare(b.name);
        return a.type === "folder" ? -1 : 1;
      });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;

    await addDoc(collection(db, "secretaria_arquivos"), {
      name,
      type: "folder",
      parentId: currentFolderId,
      createdAt: serverTimestamp(),
      createdBy: user.uid,
    });
  };

  // ✅ Upload: Storage (não Base64)
  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const clean = safeName(file.name);
      const storagePath = `secretaria_arquivos/${currentFolderId}/${Date.now()}-${clean}`;
      const { url, storagePath: savedPath } = await uploadFileToStorage(file, storagePath);

      await addDoc(collection(db, "secretaria_arquivos"), {
        name: file.name,
        type: "file",
        mimeType: file.type,
        url,
        storagePath: savedPath,
        parentId: currentFolderId,
        size: file.size,
        createdAt: serverTimestamp(),
        createdBy: user.uid,
      });

      if (fileInputRef.current) fileInputRef.current.value = "";
    } catch (err: any) {
      console.error(err);
      alert("Erro ao enviar arquivo: " + (err?.message || "desconhecido"));
    }
  };

  // ✅ Delete: Firestore + Storage
  const handleDeleteFile = async (item: FileItem) => {
    if (!confirm("Tem certeza que deseja excluir este item?")) return;

    try {
      // Se for pasta: opcionalmente bloquear se tiver filhos
      if (item.type === "folder") {
        const hasChildren = fileSystem.some((x) => x.parentId === item.id);
        if (hasChildren) {
          alert("Não é possível excluir uma pasta que contém itens. Mova ou exclua os itens primeiro.");
          return;
        }
      }

      // Remove do Storage se for arquivo
      if (item.type === "file") {
        await deleteFromStorage(item.storagePath || null);
      }

      await deleteDoc(doc(db, "secretaria_arquivos", item.id));
    } catch (err: any) {
      console.error(err);
      alert("Erro ao excluir: " + (err?.message || "desconhecido"));
    }
  };

  const handleMoveFile = async () => {
    if (!fileToMove) return;
    try {
      await updateDoc(doc(db, "secretaria_arquivos", fileToMove.id), {
        parentId: moveTargetFolderId,
        updatedAt: serverTimestamp(),
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao mover: " + (err?.message || "desconhecido"));
    }
  };

  const handleNavigate = (folder: FileItem) => {
    setCurrentFolderId(folder.id);
    setFolderPath((p) => [...p, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // ---- CHAT ----
  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    const text = chatMessage.trim();
    try {
      await addDoc(collection(db, "tickets", activeTicket.id, "messages"), {
        text,
        sender: "Secretaria",
        createdAt: serverTimestamp(),
      });

      await updateDoc(doc(db, "tickets", activeTicket.id), {
        lastMessage: text,
        updatedAt: serverTimestamp(),
        // opcional: marca como Ativo quando secretaria responde
        status: (activeTicket.status === "Pendente" ? ("Ativo" as TicketStatus) : activeTicket.status),
      });

      setChatMessage("");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao enviar mensagem: " + (err?.message || "desconhecido"));
    }
  };

  // ✅ Anexo do chat: Storage (não Base64)
  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeTicket) return;

    try {
      const clean = safeName(file.name);
      const storagePath = `tickets/${activeTicket.id}/attachments/${Date.now()}-${clean}`;
      const { url, storagePath: savedPath } = await uploadFileToStorage(file, storagePath);

      await addDoc(collection(db, "tickets", activeTicket.id, "messages"), {
        text: `Arquivo enviado: ${file.name}`,
        sender: "Secretaria",
        createdAt: serverTimestamp(),
        attachmentUrl: url,
        attachmentName: file.name,
        attachmentMimeType: file.type,
        attachmentStoragePath: savedPath,
      });

      await updateDoc(doc(db, "tickets", activeTicket.id), {
        lastMessage: `[Arquivo]: ${file.name}`,
        updatedAt: serverTimestamp(),
      });

      if (chatFileInputRef.current) chatFileInputRef.current.value = "";
    } catch (err: any) {
      console.error(err);
      alert("Erro ao enviar anexo: " + (err?.message || "desconhecido"));
    }
  };

  // --- BOT LOGIC (RETAINED) ---
  const handleBotOption = async (option: string) => {
    if(!activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: option, sender: 'Aluno', createdAt: serverTimestamp() });
    let botResponse = ''; let nextOptions: string[] = []; let escalate = false;

    switch(option) {
        case 'Problemas de Acesso': botResponse = 'Para problemas de acesso: 1. Verifique senha. 2. Redefina no perfil. 3. Limpe cache.'; nextOptions = ['Sim, resolvido', 'Não, preciso de ajuda']; break;
        case 'Material Didático': botResponse = 'O download é liberado após conclusão da aula anterior.'; nextOptions = ['Sim, resolvido', 'Não, material com erro']; break;
        case 'Aplicativo / Perfil': botResponse = 'Edite seus dados na aba "Meu Perfil".'; nextOptions = ['Sim, resolvido', 'Não, erro ao salvar']; break;
        case 'Elogio / Sugestão': botResponse = 'Digite seu elogio ou sugestão abaixo.'; break;
        case 'Reclamação': botResponse = 'Descreva o problema. Um humano analisará com prioridade.'; escalate = true; break;
        case 'Sim, resolvido': botResponse = 'Ótimo! Encerrando atendimento. Avalie nosso suporte.'; await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Resolvido' }); break;
        case 'Não, preciso de ajuda': case 'Não, material com erro': case 'Não, erro ao salvar': botResponse = 'Chamando um especialista...'; escalate = true; break;
        default: botResponse = 'Descreva sua solicitação.';
    }

    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: botResponse, sender: 'Sistema', isBot: true, options: nextOptions.length > 0 ? nextOptions : undefined, createdAt: serverTimestamp() });
    const updatePayload: any = { lastMessage: `Bot: ${option}`, updatedAt: serverTimestamp() };
    if (escalate) { updatePayload.status = 'Pendente'; updatePayload.createdAt = serverTimestamp(); }
    await updateDoc(doc(db, 'tickets', activeTicket.id), updatePayload);
  };

  const handleStudentFinalize = async () => {
    if (!activeTicket) return;
    if (!confirm("Deseja encerrar este atendimento?")) return;
    try {
      await updateDoc(doc(db, "tickets", activeTicket.id), { status: "Finalizado", updatedAt: serverTimestamp() });
      setActiveTicket((prev) => (prev ? { ...prev, status: "Finalizado" } : null));
    } catch (err: any) {
      console.error(err);
      alert("Erro ao finalizar: " + (err?.message || "desconhecido"));
    }
  };

  const submitSurveyArchive = async () => {
    if (!activeTicket) return;
    try {
      await updateDoc(doc(db, "tickets", activeTicket.id), {
        status: "Arquivado",
        archivedAt: serverTimestamp(),
      });
      setActiveTicket(null);
      setActiveTab("atendimento");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao arquivar: " + (err?.message || "desconhecido"));
    }
  };

  // ---- PDF HELPERS ----
  const formatDateLong = () => {
    const date = new Date();
    const day = date.getDate();
    const month = date.toLocaleString("pt-BR", { month: "long" });
    const year = date.getFullYear();
    return `São Paulo, ${day} de ${month} de ${year}.`;
  };

  const drawPageBorder = (docPdf: any) => {
    const w = docPdf.internal.pageSize.getWidth();
    const h = docPdf.internal.pageSize.getHeight();
    const m = 5;

    docPdf.setDrawColor(30, 41, 59);
    docPdf.setLineWidth(1);
    docPdf.rect(m, m, w - m * 2, h - m * 2);

    docPdf.setLineWidth(0.5);
    docPdf.rect(m + 2, m + 2, w - m * 2 - 4, h - m * 2 - 4);
  };

  const drawHeader = (docPdf: any, width: number, yPos: number, title: string) => {
    docPdf.setFont("times", "bold");
    docPdf.setFontSize(18);
    docPdf.setTextColor(30, 41, 59);
    docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", width / 2, yPos, { align: "center" });

    docPdf.setFont("helvetica", "normal");
    docPdf.setFontSize(8);
    docPdf.setTextColor(100);
    docPdf.text("Portaria Ministerial Nº 1004/2017 - Autorizada pelo MEC", width / 2, yPos + 5, { align: "center" });

    docPdf.setFont("times", "bold");
    docPdf.setFontSize(22);
    docPdf.setTextColor(0);
    docPdf.text(title, width / 2, yPos + 20, { align: "center" });

    return yPos + 35;
  };

  const drawStudentInfoBox = (docPdf: any, student: StudentUser, startY: number, width: number, margin: number) => {
    const boxHeight = 25;
    docPdf.setFillColor(241, 245, 249);
    docPdf.setDrawColor(200);
    docPdf.roundedRect(margin, startY, width - margin * 2, boxHeight, 3, 3, "FD");

    docPdf.setFont("helvetica", "bold");
    docPdf.setFontSize(8);
    docPdf.setTextColor(100);
    docPdf.text("DADOS DO DISCENTE", margin + 5, startY + 5);

    docPdf.setFont("helvetica", "normal");
    docPdf.setFontSize(9);
    docPdf.setTextColor(0);

    docPdf.text(`Nome Civil: ${(student.displayName || "").toUpperCase()}`, margin + 5, startY + 12);
    docPdf.text(`Curso: ${student.cursoInicial || "TEOLOGIA BÁSICA"}`, margin + 100, startY + 12);

    docPdf.text(`CPF: ${student.cpf || "000.000.000-00"}`, margin + 5, startY + 18);
    docPdf.text(`Matrícula (RA): ${student.academicId || "---"}`, margin + 100, startY + 18);

    return startY + boxHeight + 15;
  };

  // ✅ PDF: gera blob, envia pro Storage, salva metadados no Firestore
  const generateLegalPDF = async (docType: "matricula" | "conclusao" | "transferencia" | "historico") => {
    if (!opStudent) {
      alert("Selecione um aluno primeiro.");
      return;
    }

    setIsGeneratingPdf(true);
    try {
      const code = generateVerificationCode();
      const isLandscape = docType === "conclusao";

      const titles = {
        matricula: "DECLARAÇÃO DE MATRÍCULA",
        conclusao: "CERTIFICADO",
        historico: "HISTÓRICO ESCOLAR",
        transferencia: "GUIA DE TRANSFERÊNCIA",
      } as const;

      const docTitle = titles[docType];

      // Dados curso/módulos
      let modulesData: any[] = [];
      let courseData: any = {};

      if (opStudent.cursoInicial) {
        const cSnap = await getDoc(doc(db, "cursos", opStudent.cursoInicial));
        if (cSnap.exists()) courseData = cSnap.data();

        const mQuery = query(collection(db, "modulos"), where("courseId", "==", opStudent.cursoInicial), orderBy("order"));
        const mSnap = await getDocs(mQuery);
        modulesData = mSnap.docs.map((d) => d.data());
      }

      if (modulesData.length === 0) {
        modulesData = [
          { title: "Teologia Sistemática I", hours: 40, grade: 10.0 },
          { title: "Hermenêutica Bíblica", hours: 30, grade: 9.5 },
          { title: "História da Igreja", hours: 50, grade: 10.0 },
          { title: "Exegese do Novo Testamento", hours: 40, grade: 9.0 },
        ];
      }

      const validationUrl = `${window.location.origin}/verify?code=${code}`;
      const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

      // Assets (logo/assinaturas)
      const logoDataUrl = schoolConfig.logoUrl ? await fetchAsDataURL(schoolConfig.logoUrl) : null;
      const directorSigDataUrl = directorSignature ? await fetchAsDataURL(directorSignature) : null;
      const secSigDataUrl = secSignature ? await fetchAsDataURL(secSignature) : null;

      const docPdf = new jsPDF({
        orientation: isLandscape ? "landscape" : "portrait",
        unit: "mm",
        format: "a4",
      });

      const width = docPdf.internal.pageSize.getWidth();
      const height = docPdf.internal.pageSize.getHeight();
      const margin = 20;

      if (docType === "conclusao") {
        // CERTIFICADO (2 páginas, landscape)
        drawPageBorder(docPdf);

        if (logoDataUrl) {
          const logoSize = 30;
          docPdf.addImage(logoDataUrl, "PNG", width / 2 - logoSize / 2, 20, logoSize, logoSize);
        }

        docPdf.setFont("times", "bold");
        docPdf.setFontSize(36);
        docPdf.setTextColor(30, 41, 59);
        docPdf.text("CERTIFICADO", width / 2, 65, { align: "center" });

        docPdf.setFont("times", "normal");
        docPdf.setFontSize(14);
        docPdf.setTextColor(0);

        const text = `Certificamos que ${(opStudent.displayName || "").toUpperCase()}, portador(a) do CPF nº ${
          opStudent.cpf || "000.000.000-00"
        }, concluiu com êxito o curso de ${(opStudent.cursoInicial || "TEOLOGIA AVANÇADA").toUpperCase()}, cumprindo integralmente a carga horária exigida e obtendo a aprovação necessária para a outorga deste título.`;

        const textLines = docPdf.splitTextToSize(text, width - 100);
        docPdf.text(textLines, width / 2, 90, { align: "center" });

        docPdf.setFontSize(12);
        docPdf.text(formatDateLong(), width - 50, 130, { align: "right" });

        const sigY = 160;
        docPdf.setLineWidth(0.5);

        docPdf.line(60, sigY, 120, sigY);
        if (directorSigDataUrl) docPdf.addImage(directorSigDataUrl, "PNG", 70, sigY - 25, 40, 20);
        docPdf.setFontSize(10);
        docPdf.text("Diretor Acadêmico", 90, sigY + 5, { align: "center" });

        docPdf.line(width - 120, sigY, width - 60, sigY);
        if (secSigDataUrl) docPdf.addImage(secSigDataUrl, "PNG", width - 110, sigY - 25, 40, 20);
        docPdf.text("Secretaria Geral", width - 90, sigY + 5, { align: "center" });

        docPdf.setFontSize(7);
        docPdf.setTextColor(150);
        docPdf.text(`Chave de Autenticidade: ${code}`, width / 2, height - 15, { align: "center" });

        // Página 2 - Histórico
        docPdf.addPage("a4", "landscape");
        drawPageBorder(docPdf);

        docPdf.setFont("times", "bold");
        docPdf.setFontSize(16);
        docPdf.setTextColor(0);
        docPdf.text("HISTÓRICO ESCOLAR", width / 2, 30, { align: "center" });

        drawStudentInfoBox(docPdf, opStudent, 40, width, margin);

        const tableBody = modulesData.map((m: any) => [m.title || "Disciplina", (m.hours || 40) + "h", (m.grade || 10.0).toFixed(1), "APROVADO"]);

        autoTable(docPdf, {
          startY: 75,
          head: [["Disciplina / Módulo", "Carga Horária", "Nota Final", "Situação"]],
          body: tableBody,
          theme: "grid",
          headStyles: { fillColor: [30, 41, 59], halign: "center" },
          columnStyles: {
            0: { cellWidth: "auto" },
            1: { halign: "center", cellWidth: 30 },
            2: { halign: "center", cellWidth: 30 },
            3: { halign: "center", cellWidth: 40 },
          },
          styles: { fontSize: 10, cellPadding: 2 },
          margin: { left: margin, right: margin },
        });

        docPdf.addImage(qrCodeDataUrl, "PNG", margin, height - 35, 20, 20);
        docPdf.setFontSize(8);
        docPdf.text("VALIDAÇÃO DIGITAL", margin + 25, height - 28);
        docPdf.text(`Código: ${code}`, margin + 25, height - 23);
        docPdf.text(`URL: ${validationUrl}`, margin + 25, height - 18);
      } else {
        // DOCUMENTOS PORTRAIT
        drawPageBorder(docPdf);

        let cursorY = 25;
        if (logoDataUrl) {
          const logoSize = 20;
          docPdf.addImage(logoDataUrl, "PNG", width / 2 - logoSize / 2, 15, logoSize, logoSize);
          cursorY = 40;
        }

        cursorY = drawHeader(docPdf, width, cursorY, docTitle);
        cursorY = drawStudentInfoBox(docPdf, opStudent, cursorY, width, margin);

        docPdf.setFont("times", "normal");
        docPdf.setFontSize(12);

        if (docType === "historico") {
          const tableBody = modulesData.map((m: any) => [
            m.title || "Módulo Curricular",
            (m.hours || 40) + "h",
            "100%",
            (m.grade || 10.0).toFixed(1),
            "Aprovado",
          ]);

          autoTable(docPdf, {
            startY: cursorY,
            head: [["Disciplina", "C.H.", "Freq.", "Nota", "Situação"]],
            body: tableBody,
            theme: "striped",
            headStyles: { fillColor: [30, 41, 59] },
            styles: { fontSize: 10, cellPadding: 3 },
            margin: { left: margin, right: margin },
          });

          cursorY = (docPdf as any).lastAutoTable.finalY + 20;
        } else {
          cursorY += 20;
        }

        if (cursorY > height - 60) {
          docPdf.addPage();
          drawPageBorder(docPdf);
          cursorY = 40;
        }

        docPdf.setFont("times", "italic");
        docPdf.text(formatDateLong(), width - margin, cursorY, { align: "right" });

        // Footer QR
        const qrY = height - 40;
        docPdf.addImage(qrCodeDataUrl, "PNG", margin, qrY, 25, 25);
        docPdf.setFontSize(8);
        docPdf.setFont("helvetica", "bold");
        docPdf.text("AUTENTICIDADE DIGITAL", margin + 30, qrY + 8);
        docPdf.setFont("helvetica", "normal");
        docPdf.text(`Hash: ${code}`, margin + 30, qrY + 13);
        docPdf.text(`Valide em: ${validationUrl}`, margin + 30, qrY + 18);
      }

      // ✅ Blob → Storage
      const pdfBlob = docPdf.output("blob") as Blob;
      const cleanTitle = safeName(`${docTitle}-${opStudent.displayName || "aluno"}.pdf`);
      const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;
      const { url, storagePath: savedPath } = await uploadBlobToStorage(pdfBlob, storagePath, "application/pdf");

      // ✅ Firestore: salva apenas URL + metadados
      await addDoc(collection(db, "secretaria_arquivos"), {
        name: `${docTitle} - ${opStudent.displayName}.pdf`,
        type: "file",
        mimeType: "application/pdf",
        url,
        storagePath: savedPath,
        parentId: "root",
        createdAt: serverTimestamp(),
        createdBy: user.uid,
        studentId: opStudent.uid,
        docType,
        docData: {
          code,
          title: docTitle,
          date: new Date().toISOString(),
          student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
          courseData,
          modulesData,
        },
      });

      window.open(url, "_blank");
      alert("Documento gerado com sucesso!");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao gerar documento: " + (err?.message || "desconhecido"));
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  const saveEditedStudent = async () => {
    if (!editingStudent) return;
    try {
      await updateDoc(doc(db, "users", editingStudent.uid), {
        ...editingStudent,
        updatedAt: serverTimestamp(),
      });
      alert("Dados do aluno atualizados.");
      setAuditModalOpen(false);
      setEditingStudent(null);
    } catch (err: any) {
      console.error(err);
      alert("Erro ao salvar: " + (err?.message || "desconhecido"));
    }
  };

  const validateStudent = async () => {
    if (!editingStudent) return;
    try {
      await updateDoc(doc(db, "users", editingStudent.uid), {
        status: "ativo",
        updatedAt: serverTimestamp(),
      });
      alert("Matrícula validada com sucesso.");
      setAuditModalOpen(false);
      setEditingStudent(null);
    } catch (e: any) {
      alert("Erro ao validar: " + e.message);
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      {/* HEADER */}
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg shadow-lg">
            <Archive size={20} />
          </div>
          <div>
            <h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1>
            <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p>
          </div>
        </div>

        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
          {(["atendimento", "chat", "arquivos", "operacional"] as SecretariatTab[]).map((t) => (
            <button
              key={t}
              onClick={() => {
                setActiveTab(t);
                setOpSubView('main');
                if (t !== "chat") setActiveTicket(null);
              }}
              className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${
                activeTab === t ? "bg-white text-slate-900 shadow-sm" : "text-slate-400 hover:text-white"
              }`}
            >
              {t}
            </button>
          ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">
        {/* TAB: ATENDIMENTOS */}
        {activeTab === "atendimento" && (
          <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 bg-slate-50 border-b flex gap-2">
              {(["todos", "pendente", "ativo", "finalizado"] as const).map((f) => (
                <button
                  key={f}
                  onClick={() => setTicketFilter(f)}
                  className={`px-3 py-1 rounded text-[10px] font-black uppercase ${
                    ticketFilter === f ? "bg-indigo-600 text-white" : "text-slate-500"
                  }`}
                >
                  {f}
                </button>
              ))}
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              {tickets
                .filter((t) => {
                  const target = normalizeFilterStatus(ticketFilter);
                  if (!target) return true;
                  return t.status === target;
                })
                .map((t) => (
                  <div key={t.id} className="flex justify-between p-3 border-b hover:bg-slate-50 items-center">
                    <div>
                      <span className="font-bold text-xs text-indigo-700">#{t.protocolo}</span>
                      <span className="text-xs ml-2 text-slate-700">{t.user}</span>
                      <div className="text-[10px] text-slate-400">{t.lastMessage}</div>
                    </div>
                    <button
                      onClick={() => {
                        setActiveTicket(t);
                        setActiveTab("chat");
                      }}
                      className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded text-[10px] font-bold uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all"
                    >
                      Abrir
                    </button>
                  </div>
                ))}

              {tickets.length === 0 && <div className="text-center p-10 text-slate-400 text-sm">Nenhum atendimento encontrado.</div>}
            </div>
          </div>
        )}

        {/* TAB: CHAT */}
        {activeTab === "chat" && (
          <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative">
            {activeTicket ? (
              <>
                <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <div>
                    <h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Status: {activeTicket.status}</p>
                  </div>

                  {timerDisplay && (
                    <div className="flex items-center gap-2 px-3 py-1 bg-amber-50 text-amber-600 rounded-lg border border-amber-100 animate-pulse">
                      <Clock size={12} />
                      <span className="text-[10px] font-black uppercase">Espera: {timerDisplay}</span>
                    </div>
                  )}

                  <div className="flex gap-2">
                    {activeTicket.status !== "Arquivado" &&
                      activeTicket.status !== "Resolvido" &&
                      activeTicket.status !== "Finalizado" && (
                        <button
                          onClick={handleStudentFinalize}
                          className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all"
                        >
                          Encerrar Atendimento
                        </button>
                      )}

                    {(activeTicket.status === "Resolvido" || activeTicket.status === "Finalizado") && (
                      <div className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-[9px] font-black uppercase animate-pulse">
                        Pesquisa Pendente
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50 custom-scrollbar relative">
                  {messages.map((m) => (
                    <div
                      key={m.id}
                      className={`flex flex-col ${
                        m.sender === "Secretaria" || m.sender === "Sistema" ? "items-end" : "items-start"
                      }`}
                    >
                      <div
                        className={`max-w-[75%] p-3 rounded-2xl text-xs font-medium leading-relaxed shadow-sm 
                          ${
                            m.sender === "Secretaria"
                              ? "bg-indigo-600 text-white rounded-br-none"
                              : m.isBot
                              ? "bg-slate-200 text-slate-600 rounded-bl-none text-[11px]"
                              : "bg-white border border-slate-200 text-slate-700 rounded-bl-none"
                          }`}
                      >
                        {m.text}
                        {m.attachmentUrl && (
                          <div
                            onClick={() => viewAttachment(m.attachmentUrl)}
                            className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white truncate"
                          >
                            <FileText size={14} />{" "}
                            <span className="text-[9px] font-bold uppercase underline">{m.attachmentName || "Anexo"}</span>{" "}
                            <ExternalLink size={10} />
                          </div>
                        )}
                      </div>

                      {m.sender === 'Sistema' && m.options && activeTicket.status === 'Pendente' && (
                          <div className="mt-2 flex flex-wrap gap-1 justify-end">
                              {m.options.map((opt: string) => <span key={opt} className="px-2 py-1 bg-slate-100 text-slate-400 border border-slate-200 rounded text-[9px]">{opt}</span>)}
                          </div>
                      )}

                      <span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-1">{m.sender}</span>
                    </div>
                  ))}
                  <div ref={chatEndRef} />
                </div>

                {(activeTicket.status === "Resolvido" || activeTicket.status === "Finalizado") ? (
                  <div className="p-6 bg-slate-100 border-t flex flex-col items-center gap-4 text-center">
                    <h4 className="text-sm font-bold text-slate-700 uppercase">Pesquisa de Satisfação (Cliente)</h4>
                    <div className="text-xs text-slate-500">Aguardando avaliação do aluno ou arquivamento manual.</div>
                    <button
                      onClick={submitSurveyArchive}
                      className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold uppercase text-xs shadow-lg hover:bg-indigo-700"
                    >
                      Arquivar Ticket
                    </button>
                  </div>
                ) : activeTicket.status !== "Arquivado" ? (
                  <div className="p-4 border-t border-slate-100 bg-white">
                    <div className="flex gap-3 items-center">
                      <button
                        onClick={() => chatFileInputRef.current?.click()}
                        className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-indigo-100 hover:text-indigo-600 transition-all"
                      >
                        <Paperclip size={18} />
                      </button>
                      <input type="file" ref={chatFileInputRef} className="hidden" onChange={handleChatFileUpload} />

                      <input
                        value={chatMessage}
                        onChange={(e) => setChatMessage(e.target.value)}
                        onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                        className="flex-1 bg-slate-50 border-none rounded-lg py-2 px-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                        placeholder="Digite sua resposta..."
                      />

                      <button onClick={sendMessage} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-md transition-all">
                        <Send size={18} />
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 text-center bg-slate-50 text-xs text-slate-400 uppercase font-bold">Ticket Arquivado</div>
                )}
              </>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-4">
                <MessageSquare size={48} className="mb-4 opacity-20" />
                <p className="text-xs uppercase font-bold">Selecione um atendimento</p>
              </div>
            )}
          </div>
        )}

        {/* TAB: ARQUIVOS */}
        {activeTab === "arquivos" && (
          <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <div className="flex gap-1 items-center overflow-x-auto">
                <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                {folderPath.map((folder, idx) => (
                  <div key={folder.id} className="flex items-center">
                    <button
                      onClick={() => handleBreadcrumb(idx)}
                      className="text-xs font-bold text-slate-600 hover:text-indigo-600 uppercase hover:underline"
                    >
                      {folder.name}
                    </button>
                    {idx < folderPath.length - 1 && <ChevronRight size={12} className="mx-1 text-slate-300" />}
                  </div>
                ))}
              </div>

              <div className="flex gap-2">
                <button onClick={handleCreateFolder} className="p-2 bg-white border border-slate-200 rounded hover:bg-indigo-50 text-indigo-600">
                  <FolderPlus size={16} />
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 shadow-sm">
                  <UploadCloud size={16} />
                </button>
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                {currentItems.map((item) => (
                  <div
                    key={item.id}
                    className="group relative bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center justify-center gap-3 hover:shadow-md hover:border-indigo-200 transition-all cursor-pointer"
                    onClick={() => (item.type === "folder" ? handleNavigate(item) : viewFile(item))}
                  >
                    {item.type === "folder" ? (
                      <Folder size={32} className="text-indigo-400 group-hover:text-indigo-600" />
                    ) : (
                      <FileText size={32} className="text-slate-400 group-hover:text-slate-600" />
                    )}

                    <span className="text-[10px] font-bold uppercase text-center text-slate-600 truncate w-full">{item.name}</span>

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteFile(item);
                      }}
                      className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 p-1 text-rose-400 hover:bg-rose-50 rounded"
                    >
                      <Trash2 size={12} />
                    </button>

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setFileToMove(item);
                        setMoveModalOpen(true);
                      }}
                      className="absolute top-1 left-1 opacity-0 group-hover:opacity-100 p-1 text-indigo-400 hover:bg-indigo-50 rounded"
                    >
                      <Move size={12} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* TAB: OPERACIONAL */}
        {activeTab === "operacional" && (
          <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
             <div className="h-full flex flex-col md:flex-row gap-6">
              <div className="w-full md:w-64 flex flex-col gap-3 p-4 bg-slate-50/50 border-r border-slate-100">
                 <button onClick={() => setOpSubView('declaracao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => setOpSubView('certificado')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'certificado' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Award size={18}/><span className="text-xs font-black uppercase">Certificados</span></button>
                 <button onClick={() => setOpSubView('historico')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => setOpSubView('transferencia')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => setOpSubView('validacao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              <div className="flex-1 p-6 overflow-hidden relative">
                 {(opSubView === 'declaracao' || opSubView === 'certificado' || opSubView === 'historico' || opSubView === 'transferencia') && (
                   <div className="max-w-lg mx-auto space-y-6 py-6 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar Documento Oficial</h3>

                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value) || null)} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div className={`p-3 rounded-lg border text-center ${secSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Secretário</p>
                              <p className="text-xs">{secSignature ? "OK" : "Pendente"}</p>
                          </div>
                          <div className={`p-3 rounded-lg border text-center ${directorSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-amber-50 border-amber-200 text-amber-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Diretor</p>
                              <p className="text-xs">{directorSignature ? "OK" : "Pendente (Simulado)"}</p>
                          </div>
                      </div>

                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('matricula')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Printer size={14}/>} Matrícula PDF
                           </button>
                         )}
                         {opSubView === 'certificado' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Award size={14}/>} Diploma PDF
                           </button>
                         )}
                         {opSubView === 'transferencia' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('transferencia')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
