                                        <div>
                                            <p className="text-xs font-black uppercase text-slate-800">{s.displayName}</p>
                                            <p className="text-[9px] text-slate-500 font-mono">{s.cpf} • {s.email}</p>
                                        </div>
                                    </div>
                                    <button onClick={() => { setEditingStudent(s); setAuditModalOpen(true); }} className="px-4 py-2 bg-white text-rose-600 border border-rose-200 rounded-lg text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all shadow-sm">Auditar</button>
                                </div>
