                        placeholder="Digite sua resposta..."
                      />

                      <button onClick={sendMessage} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-md transition-all">
                        <Send size={18} />
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 text-center bg-slate-50 text-xs text-slate-400 uppercase font-bold">Ticket Arquivado</div>
                )}
              </>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-4">
                <MessageSquare size={48} className="mb-4 opacity-20" />
                <p className="text-xs uppercase font-bold">Selecione um atendimento</p>
              </div>
            )}
          </div>
        )}

        {/* TAB: ARQUIVOS */}
        {activeTab === "arquivos" && (
          <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
