import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  collection,
  query,
  onSnapshot,
  updateDoc,
  doc,
  serverTimestamp,
  orderBy,
  where,
  deleteDoc,
  getDoc,
  addDoc,
  getDocs,
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

import { db } from "../firebase";
import { User } from "../types";

import {
  MessageSquare,
  Search,
  FileText,
  ArrowRightLeft,
  Send,
  Archive,
  Printer,
  Folder,
  UploadCloud,
  FolderPlus,
  ChevronRight,
  ShieldCheck,
  Clock,
  Trash2,
  Move,
  ExternalLink,
  Paperclip,
  Award,
  File,
  Fingerprint,
  Home,
  UserCheck,
  RefreshCw,
  Info
} from "lucide-react";

import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import SignaturePad from '../components/SignaturePad';

import { fetchAsDataURL } from "../services/pdfAssets";
import {
  deleteFromStorage,
  safeName,
  uploadBlobToStorage,
  uploadFileToStorage,
} from "../services/storageService";

import type { FileItem, StudentUser, Ticket, TicketMessage, TicketStatus } from "../types/secretariat";

interface SecretariatViewProps {
  user: User;
}
type SecretariatTab = "atendimento" | "chat" | "arquivos" | "operacional";
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao' | 'certificado';

// ---- HELPERS ----
const generateVerificationCode = () => {
  const y = new Date().getFullYear();
  const a = Math.random().toString(36).slice(2, 6).toUpperCase();
  const b = Math.random().toString(36).slice(2, 6).toUpperCase();
  return `${y}.${a}.${b}`;
};

const normalizeFilterStatus = (filter: "todos" | "pendente" | "ativo" | "finalizado") => {
  if (filter === "pendente") return "Pendente";
  if (filter === "ativo") return "Ativo";
  if (filter === "finalizado") return "Finalizado";
  return null;
};

const viewFile = (file: FileItem) => {
  if (!file?.url) return;

  const isPdf = file.mimeType === "application/pdf" || file.name?.toLowerCase().endsWith(".pdf");
  if (isPdf) {
    const newWindow = window.open();
    if (newWindow) {
        // Se for data URL (legado) ou HTTP URL (novo storage)
        if (file.url.startsWith('data:')) {
           newWindow.document.write(
               `<iframe width='100%' height='100%' style='border:none;' src='${file.url}'></iframe>`
           );
           newWindow.document.title = file.name;
        } else {
           newWindow.location.href = file.url;
        }
    } else {
        alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
    }
    return;
  }
  window.open(file.url, "_blank");
};

const viewAttachment = (url?: string) => {
  if (!url) return;
  window.open(url, "_blank");
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>("atendimento");
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [students, setStudents] = useState<StudentUser[]>([]);
  const [fileSystem, setFileSystem] = useState<FileItem[]>([]);

  // Atendimento
  const [ticketFilter, setTicketFilter] = useState<"todos" | "pendente" | "ativo" | "finalizado">("todos");
  const [activeTicket, setActiveTicket] = useState<Ticket | null>(null);

  // Chat
  const [messages, setMessages] = useState<TicketMessage[]>([]);
  const [chatMessage, setChatMessage] = useState("");

  // General / Config
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);
  const [schoolConfig, setSchoolConfig] = useState<any>({});
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);

  // File Explorer
  const [currentFolderId, setCurrentFolderId] = useState<string>("root");
  const [folderPath, setFolderPath] = useState<{ id: string; name: string }[]>([{ id: "root", name: "Arquivos" }]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<FileItem | null>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState("root");

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Operacional
  const [opStudent, setOpStudent] = useState<StudentUser | null>(null);
  const [studentSearchTerm, setStudentSearchTerm] = useState("");
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Auditoria
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<StudentUser | null>(null);

  // Timer
  const [timerDisplay, setTimerDisplay] = useState("");
  const timerRef = useRef<number | null>(null);

  // ---- LISTENERS GLOBAIS (uma vez) ----
  useEffect(() => {
    // Tickets
    const unsubT = onSnapshot(collection(db, "tickets"), (s) => {
      const t = s.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as Ticket[];
      t.sort((a: any, b: any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
      setTickets(t);

      // Mantém activeTicket atualizado sem recriar listeners
      setActiveTicket(prev => {
        if (!prev) return null;
        const found = t.find(x => x.id === prev.id);
        return found || prev;
      });
    });

    // Arquivos
    const unsubF = onSnapshot(collection(db, "secretaria_arquivos"), (s) => {
      setFileSystem(s.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as FileItem[]);
    });

    // Alunos
    const unsubS = onSnapshot(collection(db, "users"), (s) => {
      const allUsers = s.docs.map((d) => ({ uid: d.id, ...(d.data() as any) })) as StudentUser[];
      setStudents(allUsers.filter((u) => u.role === "aluno"));
    });

    // Assinaturas
    getDoc(doc(db, "users", user.uid)).then((d) => d.exists() && setSecSignature((d.data() as any).signatureUrl || null));
    const qDir = query(collection(db, "users"), where("role", "==", "diretor"));
    getDocs(qDir).then((s) => {
      if (!s.empty) setDirectorSignature((s.docs[0].data() as any).signatureUrl || null);
    });

    // Config escola
    getDoc(doc(db, "system_settings", "main_config")).then((s) => {
      if (s.exists()) setSchoolConfig((s.data() as any).schoolConfig || {});
    });

    return () => {
      unsubT();
      unsubF();
      unsubS();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user.uid]);

  // ---- CHAT SYNC (por ticket) ----
  useEffect(() => {
    if (!activeTicket) {
      setMessages([]);
      return;
    }
    const q = query(collection(db, "tickets", activeTicket.id, "messages"), orderBy("createdAt", "asc"));
    return onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...(d.data() as any) })) as TicketMessage[];
      setMessages(list);
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: "smooth" }), 80);
    });
  }, [activeTicket?.id]);

  // ---- TIMER: só depende do id + status ----
  useEffect(() => {
    if (timerRef.current) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setTimerDisplay("");

    if (!activeTicket || activeTicket.status !== "Pendente") return;

    timerRef.current = window.setInterval(async () => {
      try {
        const now = Date.now();
        const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : now;
        const diff = now - created;
        const limit = 5 * 60 * 1000;

        if (diff >= limit) {
          // evita spam: confere no estado atual de messages
          const hasTimeoutMsg = messages.some((m) => (m.text || "").includes("todos os atendentes"));
          if (!hasTimeoutMsg && activeTicket?.id) {
            await addDoc(collection(db, "tickets", activeTicket.id, "messages"), {
              text: "Infelizmente, todos os atendentes estão ocupados. Sua solicitação foi registrada e entraremos em contato.",
              sender: "Sistema",
              isBot: true,
              createdAt: serverTimestamp(),
            });
            await updateDoc(doc(db, "tickets", activeTicket.id), {
              status: "Encaminhado",
              lastMessage: "Timeout - Encaminhado",
              updatedAt: serverTimestamp(),
            });
          }
          setTimerDisplay("Tempo esgotado");
        } else {
          const remaining = Math.ceil((limit - diff) / 1000);
          const mins = Math.floor(remaining / 60);
          const secs = remaining % 60;
          setTimerDisplay(`${mins}:${secs.toString().padStart(2, "0")}`);
        }
      } catch {
        // silencioso (evita travar UI)
      }
    }, 1000);

    return () => {
      if (timerRef.current) window.clearInterval(timerRef.current);
      timerRef.current = null;
    };
  }, [activeTicket?.id, activeTicket?.status, activeTicket?.createdAt, messages, activeTicket]);

  // ---- FILE EXPLORER ----
  const getFilesForFolder = (folderId: string) => {
    return fileSystem
      .filter((f) => f.parentId === folderId)
      .sort((a, b) => {
        if (a.type === b.type) return a.name.localeCompare(b.name);
        return a.type === "folder" ? -1 : 1;
      });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;

    await addDoc(collection(db, "secretaria_arquivos"), {
      name,
      type: "folder",
      parentId: currentFolderId,
      createdAt: serverTimestamp(),
      createdBy: user.uid,
    });
  };

  // ✅ Upload: Storage (não Base64)
  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const clean = safeName(file.name);
      const storagePath = `secretaria_arquivos/${currentFolderId}/${Date.now()}-${clean}`;
      const { url, storagePath: savedPath } = await uploadFileToStorage(file, storagePath);

      await addDoc(collection(db, "secretaria_arquivos"), {
        name: file.name,
        type: "file",
        mimeType: file.type,
        url,
        storagePath: savedPath,
        parentId: currentFolderId,
        size: file.size,
        createdAt: serverTimestamp(),
        createdBy: user.uid,
      });

      if (fileInputRef.current) fileInputRef.current.value = "";
    } catch (err: any) {
      console.error(err);
      alert("Erro ao enviar arquivo: " + (err?.message || "desconhecido"));
    }
  };

  // ✅ Delete: Firestore + Storage
  const handleDeleteFile = async (item: FileItem) => {
    if (!confirm("Tem certeza que deseja excluir este item?")) return;

    try {
      // Se for pasta: opcionalmente bloquear se tiver filhos
      if (item.type === "folder") {
        const hasChildren = fileSystem.some((x) => x.parentId === item.id);
        if (hasChildren) {
          alert("Não é possível excluir uma pasta que contém itens. Mova ou exclua os itens primeiro.");
          return;
        }
      }

      // Remove do Storage se for arquivo
      if (item.type === "file") {
        await deleteFromStorage(item.storagePath || null);
      }

      await deleteDoc(doc(db, "secretaria_arquivos", item.id));
    } catch (err: any) {
      console.error(err);
      alert("Erro ao excluir: " + (err?.message || "desconhecido"));
    }
  };

  const handleMoveFile = async () => {
    if (!fileToMove) return;
    try {
      await updateDoc(doc(db, "secretaria_arquivos", fileToMove.id), {
        parentId: moveTargetFolderId,
        updatedAt: serverTimestamp(),
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
    } catch (err: any) {
