          </div>
        </div>
      )}

      {/* MODAL AUDITORIA */}
      {auditModalOpen && editingStudent && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg">
            <h3 className="font-bold text-slate-800 mb-4 uppercase flex items-center gap-2">
              <ShieldCheck size={18} /> Auditoria de Cadastro
            </h3>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Nome Completo</label>
                <input
                  className="w-full p-2 border rounded text-xs"
                  value={editingStudent.displayName || ""}
                  onChange={(e) => setEditingStudent({ ...editingStudent, displayName: e.target.value })}
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">CPF</label>
                <input className="w-full p-2 border rounded text-xs" value={editingStudent.cpf || ""} onChange={(e) => setEditingStudent({ ...editingStudent, cpf: e.target.value })} />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Matrícula (ID)</label>
                <input className="w-full p-2 border rounded text-xs bg-slate-50" disabled value={editingStudent.academicId || ""} />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Status Acadêmico</label>
                <select
                  className="w-full p-2 border rounded text-xs"
                  value={editingStudent.status || "pendente"}
                  onChange={(e) => setEditingStudent({ ...editingStudent, status: e.target.value })}
                >
                  <option value="pendente">Pendente</option>
                  <option value="ativo">Ativo (Regular)</option>
                  <option value="bloqueado">Bloqueado</option>
                  <option value="formado">Formado</option>
                </select>
              </div>
            </div>

            <div className="mt-6 flex justify-end gap-2">
              <button
                onClick={() => {
                  setAuditModalOpen(false);
                  setEditingStudent(null);
                }}
                className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded"
              >
                Cancelar
              </button>
              <button onClick={saveEditedStudent} className="px-4 py-2 bg-indigo-600 text-white rounded text-xs font-bold hover:bg-indigo-700">
                Salvar Alterações
              </button>
              <button onClick={validateStudent} className="px-4 py-2 bg-emerald-600 text-white rounded text-xs font-bold hover:bg-emerald-700">
                Validar
              </button>
            </div>
          </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;

payload.text:
Esse erro não é do PDF — é do Firestore: você está fazendo uma query com where(...) + orderBy(...) e o Firestore exige um índice composto.

No seu código, o ponto é este (dentro do generateLegalPDF):

const mQuery = query(
  collection(db, 'modulos'),
  where('courseId', '==', opStudent.cursoInicial),
  orderBy('order')
);
const mSnap = await getDocs(mQuery);


✅ Para isso funcionar, você precisa criar um índice em Collection: modulos com:

courseId Ascending

order Ascending

Opção A (recomendado): criar o índice pelo link do erro

O Firestore já te deu o link “You can create it here”.

Clique no link que aparece no console.

Ele vai abrir o Firebase Console → Firestore → Indexes já com os campos pré-preenchidos.

Clique em Create Index.

Aguarde o status virar Enabled.

Pode levar alguns minutos. Depois disso, seu getDocs(mQuery) passa a funcionar.

Opção B: criar manualmente no Firebase Console

Se você não quiser usar o link:

Firebase Console → Firestore Database

Aba Indexes

Composite indexes → Create index

Configure:

Collection ID: modulos

Fields:

courseId → Ascending

order → Ascending

(Query scope: Collection)

Create

Opção C (paliativo rápido): remover orderBy e ordenar no client

Se você precisa rodar agora e não pode esperar o índice ficar pronto, dá pra evitar o índice assim:

const mQuery = query(
  collection(db, 'modulos'),
  where('courseId', '==', opStudent.cursoInicial)
);
const mSnap = await getDocs(mQuery);
modulesData = mSnap.docs.map(d => d.data()).sort((a:any, b:any) => (a.order ?? 0) - (b.order ?? 0));


Prós: funciona sem índice imediatamente.
Contras: para muitos módulos, pode ficar mais lento e consumir mais leitura.

Por que isso aparece “na geração do PDF”?

Porque a geração do PDF depende desse trecho para montar modulesData. Quando o Firestore bloqueia a query por falta de índice, a função cai no catch e você vê o erro no console.

Se você quiser blindar para não “quebrar” a emissão

Coloque fallback: se a query falhar, usa o array padrão (o seu código já tem um fallback de modulesData.length === 0, mas nesse caso a query não retorna, ela lança erro). Então o fallback não roda.

Troque por algo assim:

try {
  const mQuery = query(
    collection(db, 'modulos'),
    where('courseId', '==', opStudent.cursoInicial),
    orderBy('order')
  );
  const mSnap = await getDocs(mQuery);
  modulesData = mSnap.docs.map(d => d.data());
