  // ✅ PDF: gera blob, envia pro Storage, salva metadados no Firestore
  const generateLegalPDF = async (docType: "matricula" | "conclusao" | "transferencia" | "historico") => {
    if (!opStudent) {
      alert("Selecione um aluno primeiro.");
      return;
    }

    setIsGeneratingPdf(true);
    try {
      const code = generateVerificationCode();
      const isLandscape = docType === "conclusao";

      const titles = {
        matricula: "DECLARAÇÃO DE MATRÍCULA",
        conclusao: "CERTIFICADO",
        historico: "HISTÓRICO ESCOLAR",
        transferencia: "GUIA DE TRANSFERÊNCIA",
      } as const;

      const docTitle = titles[docType];

      // Dados curso/módulos
      let modulesData: any[] = [];
      let courseData: any = {};

      if (opStudent.cursoInicial) {
        const cSnap = await getDoc(doc(db, "cursos", opStudent.cursoInicial));
        if (cSnap.exists()) courseData = cSnap.data();

        // 🚨 FIX: Removed orderBy('order') to prevent 'Missing Index' error in Firestore.
        // We will sort client-side below.
        const mQuery = query(collection(db, "modulos"), where("courseId", "==", opStudent.cursoInicial));
        const mSnap = await getDocs(mQuery);
        modulesData = mSnap.docs.map((d) => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
      }

      if (modulesData.length === 0) {
        modulesData = [
          { title: "Teologia Sistemática I", hours: 40, grade: 10.0 },
          { title: "Hermenêutica Bíblica", hours: 30, grade: 9.5 },
          { title: "História da Igreja", hours: 50, grade: 10.0 },
          { title: "Exegese do Novo Testamento", hours: 40, grade: 9.0 },
        ];
      }

      const validationUrl = `${window.location.origin}/verify?code=${code}`;
      const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

      // Assets (logo/assinaturas) - USAR FETCH SEGURO PARA JSPDF
      // Helper function to avoid fetching if already data URI
      const loadAsset = async (url?: string) => {
          if (!url) return null;
          if (url.startsWith('data:')) return url;
          try {
              return await fetchAsDataURL(url);
          } catch (e) {
              console.warn("Assets failed to load, PDF will be generated without some images", e);
              return null;
          }
      };

      const logoDataUrl = await loadAsset(schoolConfig.logoUrl);
      const directorSigDataUrl = await loadAsset(directorSignature || undefined);
      const secSigDataUrl = await loadAsset(secSignature || undefined);

      const docPdf = new jsPDF({
        orientation: isLandscape ? "landscape" : "portrait",
        unit: "mm",
        format: "a4",
      });

      const width = docPdf.internal.pageSize.getWidth();
      const height = docPdf.internal.pageSize.getHeight();
      const margin = 20;

      if (docType === "conclusao") {
        // CERTIFICADO (2 páginas, landscape)
        drawPageBorder(docPdf);

        if (logoDataUrl) {
          const logoSize = 30;
          docPdf.addImage(logoDataUrl, "PNG", width / 2 - logoSize / 2, 20, logoSize, logoSize);
        }

        docPdf.setFont("times", "bold");
        docPdf.setFontSize(36);
        docPdf.setTextColor(30, 41, 59);
        docPdf.text("CERTIFICADO", width / 2, 65, { align: "center" });

        docPdf.setFont("times", "normal");
        docPdf.setFontSize(14);
        docPdf.setTextColor(0);

        const text = `Certificamos que ${(opStudent.displayName || "").toUpperCase()}, portador(a) do CPF nº ${
          opStudent.cpf || "000.000.000-00"
        }, concluiu com êxito o curso de ${(opStudent.cursoInicial || "TEOLOGIA AVANÇADA").toUpperCase()}, cumprindo integralmente a carga horária exigida e obtendo a aprovação necessária para a outorga deste título.`;

        const textLines = docPdf.splitTextToSize(text, width - 100);
        docPdf.text(textLines, width / 2, 90, { align: "center" });

        docPdf.setFontSize(12);
        docPdf.text(formatDateLong(), width - 50, 130, { align: "right" });

        const sigY = 160;
        docPdf.setLineWidth(0.5);

        docPdf.line(60, sigY, 120, sigY);
        if (directorSigDataUrl) docPdf.addImage(directorSigDataUrl, "PNG", 70, sigY - 25, 40, 20);
        docPdf.setFontSize(10);
        docPdf.text("Diretor Acadêmico", 90, sigY + 5, { align: "center" });

        docPdf.line(width - 120, sigY, width - 60, sigY);
        if (secSigDataUrl) docPdf.addImage(secSigDataUrl, "PNG", width - 110, sigY - 25, 40, 20);
        docPdf.text("Secretaria Geral", width - 90, sigY + 5, { align: "center" });

        docPdf.setFontSize(7);
        docPdf.setTextColor(150);
        docPdf.text(`Chave de Autenticidade: ${code}`, width / 2, height - 15, { align: "center" });

        // Página 2 - Histórico
        docPdf.addPage("a4", "landscape");
        drawPageBorder(docPdf);

        docPdf.setFont("times", "bold");
        docPdf.setFontSize(16);
        docPdf.setTextColor(0);
        docPdf.text("HISTÓRICO ESCOLAR", width / 2, 30, { align: "center" });

        drawStudentInfoBox(docPdf, opStudent, 40, width, margin);

        const tableBody = modulesData.map((m: any) => [m.title || "Disciplina", (m.hours || 40) + "h", (m.grade || 10.0).toFixed(1), "APROVADO"]);

        autoTable(docPdf, {
          startY: 75,
          head: [["Disciplina / Módulo", "Carga Horária", "Nota Final", "Situação"]],
          body: tableBody,
          theme: "grid",
          headStyles: { fillColor: [30, 41, 59], halign: "center" },
          columnStyles: {
            0: { cellWidth: "auto" },
            1: { halign: "center", cellWidth: 30 },
            2: { halign: "center", cellWidth: 30 },
            3: { halign: "center", cellWidth: 40 },
          },
          styles: { fontSize: 10, cellPadding: 2 },
          margin: { left: margin, right: margin },
        });

        docPdf.addImage(qrCodeDataUrl, "PNG", margin, height - 35, 20, 20);
        docPdf.setFontSize(8);
        docPdf.text("VALIDAÇÃO DIGITAL", margin + 25, height - 28);
        docPdf.text(`Código: ${code}`, margin + 25, height - 23);
        docPdf.text(`URL: ${validationUrl}`, margin + 25, height - 18);
      } else {
        // DOCUMENTOS PORTRAIT
        drawPageBorder(docPdf);

        let cursorY = 25;
        if (logoDataUrl) {
          const logoSize = 20;
          docPdf.addImage(logoDataUrl, "PNG", width / 2 - logoSize / 2, 15, logoSize, logoSize);
          cursorY = 40;
        }

        cursorY = drawHeader(docPdf, width, cursorY, docTitle);
        cursorY = drawStudentInfoBox(docPdf, opStudent, cursorY, width, margin);

        docPdf.setFont("times", "normal");
        docPdf.setFontSize(12);

        if (docType === "historico") {
          const tableBody = modulesData.map((m: any) => [
            m.title || "Módulo Curricular",
            (m.hours || 40) + "h",
            "100%",
            (m.grade || 10.0).toFixed(1),
            "Aprovado",
          ]);

          autoTable(docPdf, {
            startY: cursorY,
            head: [["Disciplina", "C.H.", "Freq.", "Nota", "Situação"]],
            body: tableBody,
            theme: "striped",
            headStyles: { fillColor: [30, 41, 59] },
            styles: { fontSize: 10, cellPadding: 3 },
            margin: { left: margin, right: margin },
          });

          cursorY = (docPdf as any).lastAutoTable.finalY + 20;
        } else {
          cursorY += 20;
        }

        if (cursorY > height - 60) {
          docPdf.addPage();
          drawPageBorder(docPdf);
          cursorY = 40;
