/**
 * Sanitizes filenames to prevent path issues in Storage.
 */
export function safeName(name: string) {
  return (name || "arquivo")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // Remove accents
    .replace(/[^\w.\-]+/g, "_")      // Keep only alphanumeric, dot, hyphen
    .replace(/_+/g, "_")             // Collapse underscores
    .slice(0, 140);                  // Limit length
}

/**
 * Upload a File object using Firebase SDK.
 */
export async function uploadFileToStorage(
  file: File,
  storagePath: string
): Promise<{ url: string; storagePath: string }> {
  const storageRef = ref(storage, storagePath);

  // Using the SDK automatically handles Content-Type and CORS preflight logic correctly
  await uploadBytes(storageRef, file, { 
    contentType: file.type || 'application/octet-stream' 
  });

  const url = await getDownloadURL(storageRef);
  return { url, storagePath };
}

/**
 * Upload a Blob object (e.g. PDF generated client-side).
 */
export async function uploadBlobToStorage(
  blob: Blob,
  storagePath: string,
  contentType: string = 'application/octet-stream'
): Promise<{ url: string; storagePath: string }> {
  const storageRef = ref(storage, storagePath);

  await uploadBytes(storageRef, blob, { contentType });

  const url = await getDownloadURL(storageRef);
  return { url, storagePath };
}

/**
 * Deletes a file from storage.
 */
export async function deleteFromStorage(storagePath?: string | null) {
  if (!storagePath) return;
  try {
    const storageRef = ref(storage, storagePath);
    await deleteObject(storageRef);
  } catch (error: any) {
    console.warn("Error deleting file from storage:", error.message);
    // Suppress 404s (object not found)
  }
}

export async function fetchAsDataURL(url: string): Promise<string> {
  // If it's already a Data URI, return immediately (no network request needed)
  if (url.startsWith('data:')) {
    return url;
  }

  // If it's an external URL, attempt to fetch and convert
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Falha ao baixar asset: ${url}`);
    const blob = await res.blob();

    return await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result));
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.error("PDF Asset Load Error:", error);
    throw error;
  }
}

