  console.log("Storage Upload [File] - Auth User UID:", auth.currentUser?.uid || 'Unauthenticated');

  const storageRef = ref(storage, storagePath);

  // Minimal metadata to avoid strict CORS preflight rejections (e.g. removing Cache-Control)
  const metadata = {
    contentType: file.type || 'application/octet-stream',
  };

  try {
    await uploadBytes(storageRef, file, metadata);
    const url = await getDownloadURL(storageRef);
    return { url, storagePath };
  } catch (error: any) {
    console.error("Storage Upload Error:", error);
    if (error.code === 'storage/unauthorized') {
      throw new Error("Permissão negada. Verifique se você está logado e tem acesso.");
    }
    throw error;
  }
}

/**
 * Upload a Blob object (e.g. PDF generated client-side).
 */
export async function uploadBlobToStorage(
