import {
  ref,
  uploadBytes,
  getDownloadURL,
  deleteObject,
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-storage.js";
import { getAuth } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { storage } from "../firebase";

/**
 * Sanitizes filenames to prevent path issues in Storage.
 */
export function safeName(name: string) {
  return (name || "arquivo")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // Remove accents
    .replace(/[^\w.\-]+/g, "_")      // Keep only alphanumeric, dot, hyphen
    .replace(/_+/g, "_")             // Collapse underscores
    .slice(0, 140);                  // Limit length
}

/**
 * Helper to convert Blob/File to Data URI (Base64)
 * Used as a fallback when Cloud Storage fails.
 */
const blobToDataURL = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

/**
 * Upload a File object using Firebase SDK.
 * Includes Fallback to Base64 if CORS fails.
 */
export async function uploadFileToStorage(
  file: File,
  storagePath: string
): Promise<{ url: string; storagePath: string }> {
  // Debug Auth State
  const auth = getAuth();
  console.log("Storage Upload [File] - Auth User UID:", auth.currentUser?.uid || 'Unauthenticated');

  const storageRef = ref(storage, storagePath);
  const metadata = {
    contentType: file.type || 'application/octet-stream',
  };

  try {
    await uploadBytes(storageRef, file, metadata);
    const url = await getDownloadURL(storageRef);
    return { url, storagePath };
  } catch (error: any) {
    console.warn("Storage Upload Failed (CORS/Network). Using Local Fallback.", error);

    // FALLBACK: Return Base64 so the app continues working
    const base64Url = await blobToDataURL(file);
    return { url: base64Url, storagePath: "" }; // Empty storagePath indicates local storage
  }
}

/**
 * Upload a Blob object (e.g. PDF generated client-side).
 * Includes Fallback to Base64 if CORS fails.
 */
export async function uploadBlobToStorage(
  blob: Blob,
  storagePath: string,
  contentType: string = 'application/octet-stream'
): Promise<{ url: string; storagePath: string }> {
  // Debug Auth State
  const auth = getAuth();
  console.log("Storage Upload [Blob] - Auth User UID:", auth.currentUser?.uid || 'Unauthenticated');

  const storageRef = ref(storage, storagePath);
  const metadata = {
    contentType: contentType,
  };

  try {
    await uploadBytes(storageRef, blob, metadata);
    const url = await getDownloadURL(storageRef);
    return { url, storagePath };
  } catch (error: any) {
    console.warn("Blob Upload Failed (CORS/Network). Using Local Fallback.", error);

    // FALLBACK: Return Base64 so the PDF still opens/saves
    const base64Url = await blobToDataURL(blob);
    return { url: base64Url, storagePath: "" };
  }
}

/**
 * Deletes a file from storage.
 */
export async function deleteFromStorage(storagePath?: string | null) {
  if (!storagePath) return; // Ignore if it was a local fallback (empty path)
  try {
    const storageRef = ref(storage, storagePath);
    await deleteObject(storageRef);
  } catch (error: any) {
    console.warn("Error deleting file from storage:", error.message);
    // Suppress 404s (object not found)
  }
}

