                  : [["Teologia Sistemática", "40h", "100%", "10.0", "APROVADO"], ["Hermenêutica", "30h", "100%", "9.5", "APROVADO"]];

              autoTable(docPdf, {
                  startY: y,
                  head: [['Disciplina', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
              });
              y = (docPdf as any).lastAutoTable.finalY + 20;
          }

          // Assinaturas e Footer
          const sigY = height - 60;
          if (directorSigDataUrl) docPdf.addImage(directorSigDataUrl, 'PNG', margin + 10, sigY - 20, 40, 20);
          docPdf.text("Diretor", margin + 20, sigY + 5);

          if (secSigDataUrl) docPdf.addImage(secSigDataUrl, 'PNG', width - margin - 50, sigY - 20, 40, 20);
          docPdf.text("Secretaria", width - margin - 40, sigY + 5);

          docPdf.addImage(qrCodeDataUrl, 'PNG', margin, height - 35, 20, 20);
          docPdf.setFontSize(7);
          docPdf.text(`Validação: ${code}`, margin + 25, height - 25);

          // ---------------------------------------------------------
          // CRITICAL FIX: OPEN PDF IMMEDIATELY BEFORE STORAGE ATTEMPT
          // ---------------------------------------------------------
          const pdfBlob = docPdf.output('blob');
          const localUrl = URL.createObjectURL(pdfBlob);
          window.open(localUrl, '_blank'); // Immediate User Feedback

          // Background Storage Persistence
          try {
              const cleanTitle = safeName(`${docTitle}-${opStudent.displayName || "aluno"}.pdf`);
              const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;

              const { url, storagePath: savedPath } = await uploadBlobToStorage(pdfBlob, storagePath, 'application/pdf');

              // Safety: Don't crash Firestore with huge base64 strings if upload failed
              let firestoreUrl = url;
              if (url.startsWith('data:') && url.length > 900000) {
                  firestoreUrl = ""; // Placeholder
                  console.warn("PDF too large for Firestore and Storage failed. Not saving body.");
              }

              // Salvar no sistema de arquivos virtual
              await addDoc(collection(db, 'secretaria_arquivos'), {
                  name: `${docTitle} - ${opStudent.displayName}.pdf`,
                  type: 'file', mimeType: 'application/pdf', url: firestoreUrl,
                  storagePath: savedPath,
                  parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
