import {
  getStorage,
  ref,
  uploadBytes,
  getDownloadURL,
  deleteObject,
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-storage.js";

// ----------------------------------------------------
// Helpers
// ----------------------------------------------------
export const safeName = (name: string) => {
  return (name || "arquivo")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w.\-]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
};

const isLikelyCorsOrNetwork = (err: any) => {
  const msg = String(err?.message || err || "").toLowerCase();
  return (
    msg.includes("cors") ||
    msg.includes("preflight") ||
    msg.includes("failed to fetch") ||
    msg.includes("network") ||
    msg.includes("net::err_failed") ||
    msg.includes("err_failed") ||
    msg.includes("typeerror: failed to fetch") ||
    msg.includes("storage/unauthorized")
  );
};

export type UploadResult = {
  ok: boolean;
  url: string;                // quando ok=true -> URL do Storage; quando ok=false -> blob: URL local (sessão)
  storagePath: string | null; // quando ok=true -> path; quando ok=false -> null
  fallbackReason?: "cors_or_network" | "upload_failed";
};

// ----------------------------------------------------
// Uploads
// ----------------------------------------------------
export async function uploadBlobToStorage(
  blob: Blob,
  storagePath: string,
  contentType = "application/pdf"
): Promise<UploadResult> {
  try {
    const storage = getStorage();
    const r = ref(storage, storagePath);

    await uploadBytes(r, blob, { contentType });
    const url = await getDownloadURL(r);

    return { ok: true, url, storagePath };
  } catch (err: any) {
    console.error("[uploadBlobToStorage] failed:", err);

    // ✅ Fallback: URL local (não grava base64 no Firestore)
    const localUrl = URL.createObjectURL(blob);
    return {
      ok: false,
      url: localUrl,
      storagePath: null,
      fallbackReason: isLikelyCorsOrNetwork(err) ? "cors_or_network" : "upload_failed",
    };
  }
}

export async function uploadFileToStorage(
  file: File,
  storagePath: string
): Promise<UploadResult> {
  try {
    const storage = getStorage();
    const r = ref(storage, storagePath);

    await uploadBytes(r, file, { contentType: file.type || "application/octet-stream" });
    const url = await getDownloadURL(r);

    return { ok: true, url, storagePath };
  } catch (err: any) {
    console.error("[uploadFileToStorage] failed:", err);

    const localUrl = URL.createObjectURL(file);
    return {
      ok: false,
      url: localUrl,
      storagePath: null,
      fallbackReason: isLikelyCorsOrNetwork(err) ? "cors_or_network" : "upload_failed",
    };
  }
}

// ----------------------------------------------------
// Delete
// ----------------------------------------------------
export async function deleteFromStorage(storagePath?: string | null) {
  if (!storagePath) return;
  try {
    const storage = getStorage();
    const r = ref(storage, storagePath);
    await deleteObject(r);
  } catch (e) {
    console.warn("Delete failed (might be local fallback):", e);
  }
}

