export const uploadBlobToStorage = async (
  blob: Blob,
  path: string,
  onProgress?: (progress: number) => void
): Promise<string | null> => {
  if (storageCircuitOpen) {
    console.warn("Storage circuit open, skipping upload");
    return null;
