                            </div>
                        ))}
                     </div>
                     <div className="flex gap-2">
                        <button onClick={handleCreateFolder} className="p-2 bg-white border border-slate-200 rounded hover:bg-indigo-50 text-indigo-600"><FolderPlus size={16}/></button>
