             textData = `Certificamos, para os devidos fins de direito, que ${studentName}, portador(a) do CPF nº ${studentCpf} e matrícula acadêmica ${studentId}, CONCLUIU com êxito o curso de ${courseName}, cumprindo integralmente a carga horária, os requisitos acadêmicos e as avaliações previstas no projeto pedagógico desta instituição de ensino.`;
          } else if (docType === 'matricula') {
             textData = `Declaramos, a quem possa interessar, que o(a) aluno(a) ${studentName}, inscrito(a) no CPF nº ${studentCpf} e matrícula ${studentId}, encontra-se regularmente MATRICULADO(A) no curso de ${courseName} desta instituição, frequentando as atividades letivas do presente período.`;
          } else if (docType === 'transferencia') {
             textData = `Atestamos a transferência do(a) discente ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, do curso de ${courseName}, estando apto(a) a prosseguir seus estudos na instituição de destino, conforme legislação vigente.`;
          } else {
             textData = `Certificamos o Histórico Escolar do(a) aluno(a) ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, referente ao curso de ${courseName}, conforme detalhamento de notas e frequência apresentado a seguir.`;
          }

          const lines = docPdf.splitTextToSize(textData, width - (margin*2));
          docPdf.text(lines, margin, y + 20); // Add some spacing after header

          y += 20 + (lines.length * 8) + 30; // Push Y down

          // Date & Place (Page 1)
          const dateStr = new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
          docPdf.setFont("times", "italic");
          docPdf.setFontSize(12);
          docPdf.text(`São Paulo, ${dateStr}.`, width - margin, y, { align: "right" });

          // Signatures (Page 1)
          const sigY = height - 60;
          if (directorSigDataUrl) docPdf.addImage(directorSigDataUrl, 'PNG', margin + 10, sigY - 20, 40, 20);
          docPdf.setLineWidth(0.5);
          docPdf.line(margin + 10, sigY, margin + 60, sigY);
          docPdf.setFont("helvetica", "bold");
          docPdf.setFontSize(8);
          docPdf.text("DIRETORIA EXECUTIVA", margin + 35, sigY + 5, { align: "center" });

          if (secSigDataUrl) docPdf.addImage(secSigDataUrl, 'PNG', width - margin - 60, sigY - 20, 40, 20);
          docPdf.line(width - margin - 60, sigY, width - margin - 10, sigY);
          docPdf.text("SECRETARIA GERAL", width - margin - 35, sigY + 5, { align: "center" });

          // PAGE 2: HISTORY & SCHEDULE (If applicable or always included for verification)
          docPdf.addPage();
          drawPageBorder(docPdf);

          // Simple Header Page 2
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(16);
          docPdf.setTextColor(30, 41, 59);
          docPdf.text("HISTÓRICO E CRONOGRAMA", width/2, 25, { align: "center" });
          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "normal");
          docPdf.text(`Aluno: ${studentName} | RA: ${studentId}`, width/2, 32, { align: "center" });

          let y2 = 45;

          // Table
          const tableBody = modulesData.length > 0 
              ? modulesData.map((m: any) => [m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"])
              : [["Teologia Sistemática", "40h", "100%", "10.0", "APROVADO"], ["Hermenêutica", "30h", "100%", "9.5", "APROVADO"]];

          autoTable(docPdf, {
              startY: y2,
              head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']],
              body: tableBody,
              theme: 'grid',
              headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
              styles: { fontSize: 9, font: 'helvetica' }
          });

          // QR Code at Bottom of Page 2
          docPdf.addImage(qrCodeDataUrl, 'PNG', (width/2) - 15, height - 50, 30, 30);
          docPdf.setFontSize(8);
          docPdf.setFont("helvetica", "bold");
          docPdf.text("VALIDAÇÃO DIGITAL", width/2, height - 15, {align: "center"});
          docPdf.setFont("helvetica", "normal");
          docPdf.text(`Código: ${code}`, width/2, height - 10, {align: "center"});
          docPdf.text(validationUrl, width/2, height - 6, {align: "center"});

          // ---------------------------------------------------------
          // SAFE GENERATION AND FALLBACK
          // ---------------------------------------------------------
          const pdfBlob = docPdf.output('blob');
          const localUrl = URL.createObjectURL(pdfBlob);
          window.open(localUrl, '_blank'); // Immediate User Feedback

          // Robust Storage Logic with Circuit Breaker
          try {
              const cleanTitle = safeName(`${docTitle}-${opStudent.displayName || "aluno"}.pdf`);
              const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;

              const uploadResult = await uploadBlobToStorage(pdfBlob, storagePath, 'application/pdf');

              await addDoc(collection(db, 'secretaria_arquivos'), {
                  name: `${docTitle} - ${opStudent.displayName}.pdf`,
                  type: 'file', mimeType: 'application/pdf', 
                  url: uploadResult.ok ? uploadResult.url : "", 
                  storagePath: uploadResult.ok ? uploadResult.storagePath : null,
                  storageStatus: uploadResult.ok ? 'uploaded' : `fallback_${uploadResult.fallbackReason}`,
                  parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
                  studentId: opStudent.uid, docType: docType,
                  docData: {
                      code, title: docTitle, date: new Date().toISOString(),
                      student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
                      courseData, modulesData
                  }
              });

              if (!uploadResult.ok) {
                  console.warn("PDF generated locally (Storage upload skipped/failed).");
              } 

          } catch (storageError: any) {
              // Prevent circular structure error by logging only message
              console.error("Critical Storage Error:", storageError.message || "Unknown storage error");
          }

