// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewFile = (file: any) => {
  if (!file) return;

  if (!file.url && file.storageStatus?.startsWith('fallback')) {
      alert("Este arquivo não foi salvo na nuvem devido a um erro de upload/rede. Tente gerar o documento novamente para persistir.");
      return;
  }

  if (!file.url) {
      alert("Arquivo sem URL válida.");
      return;
  }

  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(
                 `<iframe width='100%' height='100%' style='border:none;' src='${file.url}'></iframe>`
             );
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }
  window.open(file.url, '_blank');
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http') || url.startsWith('blob:')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        try {
            const byteString = atob(url.split(',')[1]);
            const mimeString = url.split(',')[0].split(':')[1].split(';')[0];
            const ab = new ArrayBuffer(byteString.length);
            const ia = new Uint8Array(ab);
            for (let i = 0; i < byteString.length; i++) { ia[i] = byteString.charCodeAt(i); }
            const blob = new Blob([ab], {type: mimeString});
            const blobUrl = URL.createObjectURL(blob);
            const win = window.open(blobUrl, '_blank');
            if (!win) { alert("Pop-up bloqueado. Permita pop-ups para ver o anexo."); }
        } catch (e) { console.error("Erro ao abrir anexo:", e); alert("Erro ao abrir anexo."); }
        return;
    }
};

// --- PDF DRAWING HELPERS ---
const drawPageBorder = (doc: any) => {
    const w = doc.internal.pageSize.getWidth();
    const h = doc.internal.pageSize.getHeight();
    const m = 5;

    // Outer Border
    doc.setDrawColor(30, 41, 59); // Slate-900 like
    doc.setLineWidth(0.8);
    doc.rect(m, m, w - (m*2), h - (m*2));

    // Inner Border
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.3);
    doc.rect(m+2, m+2, w - (m*2) - 4, h - (m*2) - 4);
};

const drawHeader = (doc: any, schoolConfig: any, title: string, logo: string | null) => {
    const w = doc.internal.pageSize.getWidth();
    let y = 20;

    if (logo) {
        try {
            doc.addImage(logo, 'PNG', 20, 15, 25, 25);
        } catch(e) {}
    }

    doc.setFont("times", "bold");
    doc.setFontSize(24);
    doc.setTextColor(30, 41, 59);
    doc.text((schoolConfig.schoolName || "ESCOLA BÍBLICA EAD").toUpperCase(), w/2, 25, { align: "center" });

    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(100);
    doc.text("Instituição de Ensino Teológico - Portaria Nº 1004/2017", w/2, 32, { align: "center" });
    if(schoolConfig.cnpj) doc.text(`CNPJ: ${schoolConfig.cnpj}`, w/2, 36, { align: "center" });

    // Line Divider
    doc.setDrawColor(30, 41, 59);
    doc.setLineWidth(0.5);
    doc.line(20, 45, w-20, 45);

    doc.setFont("times", "bold");
    doc.setFontSize(22);
    doc.setTextColor(0);
    doc.text(title, w/2, 65, { align: "center" });

    return 80; // Start Y for content
};

