        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name, type: 'file', mimeType: file.type, 
          url: uploadResult.ok ? uploadResult.url : "", 
          storagePath: uploadResult.ok ? uploadResult.storagePath : null,
          storageStatus: uploadResult.ok ? 'uploaded' : `fallback_${uploadResult.fallbackReason}`,
          parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid
        });

