    if (g && doc.setGState) doc.setGState(new (doc as any).GState({ opacity: 1 }));
  } catch {
    // ignore watermark failures
  }
};

const drawSectionTitle = (doc: any, text: string, x: number, y: number) => {
  setText(doc, "helvetica", "bold", 10, BRAND.primary);
  doc.text(text.toUpperCase(), x, y);
  doc.setDrawColor(226,232,240);
  doc.setLineWidth(0.4);
  doc.line(x, y+2, x+80, y+2);
};

const drawInfoGrid = (doc: any, x: number, y: number, w: number, rows: {label: string, value: string}[]) => {
  // background card
  doc.setFillColor(...BRAND.light);
  doc.roundedRect(x, y, w, rows.length*8 + 8, 2, 2, "F");
  doc.setDrawColor(226,232,240);
  doc.setLineWidth(0.4);
  doc.roundedRect(x, y, w, rows.length*8 + 8, 2, 2, "S");

  let cy = y + 7;
  rows.forEach((r) => {
    setText(doc, "helvetica", "bold", 7, BRAND.muted);
    doc.text(r.label.toUpperCase(), x + 6, cy);

    setText(doc, "helvetica", "normal", 10, [15,23,42]);
    doc.text(r.value || "---", x + 6, cy + 4);

    cy += 8;
  });
};

const drawCertificateBadge = (doc: any, label: string) => {
  const w = doc.internal.pageSize.getWidth();
  const x = w - 62;
  const y = 26;
  const bw = 52;
  const bh = 14;

  doc.setFillColor(...BRAND.secondary);
  doc.roundedRect(x, y, bw, bh, 3, 3, "F");

  setText(doc, "helvetica", "bold", 9, [255,255,255]);
  doc.text(label.toUpperCase(), x + bw/2, y + 9.5, { align: "center" });
};

const drawFooterValidation = (doc: any, validationUrl: string, code: string, qrCodeDataUrl: string) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  const y = h - 26;

  doc.setDrawColor(226,232,240);
  doc.setLineWidth(0.4);
  doc.line(10, y, w-10, y);

  // QR
  try { doc.addImage(qrCodeDataUrl, "PNG", 12, y + 2, 18, 18); } catch {}

  setText(doc, "helvetica", "bold", 8, BRAND.primary);
  doc.text("VALIDAÇÃO DIGITAL", 34, y + 8);

  setText(doc, "helvetica", "normal", 7, BRAND.muted);
  doc.text(`Código: ${code}`, 34, y + 13);

  // URL (truncate)
  const url = validationUrl.length > 70 ? validationUrl.slice(0, 70) + "…" : validationUrl;
  doc.text(url, 34, y + 18);

  setText(doc, "helvetica", "italic", 7, BRAND.muted);
  doc.text("Documento assinado digitalmente e verificável via QR Code.", w - 10, y + 18, { align: "right" });
};

const drawSignaturesRow = (doc: any, directorSig: string | null, secSig: string | null, leftLabel: string, rightLabel: string) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();

  const baseY = h - 55;
  const lineY = baseY + 18;

  // Left
  if (directorSig) { try { doc.addImage(directorSig, "PNG", 28, baseY, 40, 18); } catch {} }
  doc.setDrawColor(148,163,184);
  doc.setLineWidth(0.4);
  doc.line(22, lineY, 78, lineY);

  setText(doc, "helvetica", "bold", 8, BRAND.primary);
  doc.text(leftLabel.toUpperCase(), 50, lineY + 5, { align: "center" });

  // Right
  if (secSig) { try { doc.addImage(secSig, "PNG", w - 68, baseY, 40, 18); } catch {} }
  doc.line(w - 78, lineY, w - 22, lineY);

  setText(doc, "helvetica", "bold", 8, BRAND.primary);
  doc.text(rightLabel.toUpperCase(), w - 50, lineY + 5, { align: "center" });
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]); 
  const [chatMessage, setChatMessage] = useState('');

  // UI States - General
  const [secSignature, setSecSignature] = useState<string | null>(null); 
  const [directorSignature, setDirectorSignature] = useState<string | null>(null); 
  const [schoolConfig, setSchoolConfig] = useState<any>({});

  // File Explorer & Save States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  // Timer & Survey
  const [timerDisplay, setTimerDisplay] = useState<string>('');
  const [survey, setSurvey] = useState({ demandMet: null as boolean|null, problemSolved: null as boolean|null, likedChat: null as boolean|null, rating: 0 });

  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- EFFECTS ---
  useEffect(() => {
    // Ticket Listener
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Fetch Signatures & Config
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => {
        if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl);
    });
    getDoc(doc(db, "system_settings", "main_config")).then((s) => {
      if (s.exists()) setSchoolConfig((s.data() as any).schoolConfig || {});
    });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  // Sync Chat
  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  // Timer Logic
  useEffect(() => {
    let interval: any;
    if (activeTicket && activeTicket.status === 'Pendente') {
        interval = setInterval(async () => {
            const now = Date.now();
            const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : Date.now();
            const diff = now - created;
            const limit = 5 * 60 * 1000;
            if (diff >= limit) {
                const hasTimeoutMsg = messages.some((m: any) => m.text.includes("todos os atendentes"));
                if (!hasTimeoutMsg) {
                    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                        text: "Infelizmente, todos os atendentes estão ocupados. Sua solicitação foi registrada e entraremos em contato.",
                        sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
                    });
                    await updateDoc(doc(db, 'tickets', activeTicket.id), {
                        status: 'Encaminhado', lastMessage: "Timeout - Encaminhado", updatedAt: serverTimestamp()
                    });
                }
                setTimerDisplay("Tempo esgotado");
            } else {
                const remaining = Math.ceil((limit - diff) / 1000);
                const mins = Math.floor(remaining / 60);
                const secs = remaining % 60;
                setTimerDisplay(`${mins}:${secs.toString().padStart(2, '0')}`);
            }
        }, 1000);
    } else { setTimerDisplay(''); }
    return () => clearInterval(interval);
  }, [activeTicket, messages]);

  // --- FILE EXPLORER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
        const clean = safeName(file.name);
        const storagePath = `secretaria_arquivos/${currentFolderId}/${Date.now()}-${clean}`;
        const uploadResult = await uploadFileToStorage(file, storagePath);

        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name, type: 'file', mimeType: file.type, 
          url: uploadResult.ok ? uploadResult.url : "", 
          storagePath: uploadResult.ok ? uploadResult.storagePath : null,
          storageStatus: uploadResult.ok ? 'uploaded' : `fallback_${uploadResult.fallbackReason}`,
          parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid
        });

        if (!uploadResult.ok) {
            alert("O arquivo foi listado, mas o upload para nuvem falhou. Tente novamente mais tarde.");
        }
    } catch(e) {
        alert("Erro crítico no upload.");
    }
  };

  const handleDeleteFile = async (item: any) => {
      if(confirm('Tem certeza que deseja excluir este item?')) {
          if (item.type === 'file' && item.storagePath) await deleteFromStorage(item.storagePath);
          await deleteDoc(doc(db, 'secretaria_arquivos', item.id));
      }
  }

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId, updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- CHAT FUNCTIONS ---
  const handleBotOption = async (option: string) => {
    if(!activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: option, sender: 'Aluno', createdAt: serverTimestamp() });
    let botResponse = ''; let nextOptions: string[] = []; let escalate = false;

    switch(option) {
        case 'Problemas de Acesso': botResponse = 'Para problemas de acesso: 1. Verifique senha. 2. Redefina no perfil. 3. Limpe cache.'; nextOptions = ['Sim, resolvido', 'Não, preciso de ajuda']; break;
        case 'Material Didático': botResponse = 'O download é liberado após conclusão da aula anterior.'; nextOptions = ['Sim, resolvido', 'Não, material com erro']; break;
        case 'Aplicativo / Perfil': botResponse = 'Edite seus dados na aba "Meu Perfil".'; nextOptions = ['Sim, resolvido', 'Não, erro ao salvar']; break;
        case 'Elogio / Sugestão': botResponse = 'Digite seu elogio ou sugestão abaixo.'; break;
        case 'Reclamação': botResponse = 'Descreva o problema. Um humano analisará com prioridade.'; escalate = true; break;
        case 'Sim, resolvido': botResponse = 'Ótimo! Encerrando atendimento. Avalie nosso suporte.'; await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Resolvido' }); break;
        case 'Não, preciso de ajuda': case 'Não, material com erro': case 'Não, erro ao salvar': botResponse = 'Chamando um especialista...'; escalate = true; break;
        default: botResponse = 'Descreva sua solicitação.';
    }

    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: botResponse, sender: 'Sistema', isBot: true, options: nextOptions.length > 0 ? nextOptions : undefined, createdAt: serverTimestamp() });
    const updatePayload: any = { lastMessage: `Bot: ${option}`, updatedAt: serverTimestamp() };
    if (escalate) { updatePayload.status = 'Pendente'; updatePayload.createdAt = serverTimestamp(); } // Reset timer on escalation
    await updateDoc(doc(db, 'tickets', activeTicket.id), updatePayload);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Secretaria', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file || !activeTicket) return;
    try {
        const clean = safeName(file.name);
        const uploadResult = await uploadFileToStorage(file, `tickets/${activeTicket.id}/${clean}`);

        const safeUrl = uploadResult.ok ? uploadResult.url : ""; 

        await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { 
            text: `Arquivo enviado: ${file.name}`, attachmentUrl: safeUrl, sender: 'Secretaria', createdAt: serverTimestamp() 
        }); 
        await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: `[Arquivo]: ${file.name}`, updatedAt: serverTimestamp() }); 

        if(!uploadResult.ok) alert("Aviso: Upload falhou, anexo pode não estar visível.");
    } catch(e) { console.error(e); alert("Erro ao enviar anexo."); }
  };

  const handleStudentFinalize = async () => {
    if(!activeTicket) return;
    if(!confirm("Deseja encerrar este atendimento?")) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Finalizado', updatedAt: serverTimestamp() });
    setActiveTicket((prev: any) => prev ? {...prev, status: 'Finalizado'} : null);
  };

  const submitSurvey = async () => {
    if (!activeTicket) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Arquivado', survey: survey, archivedAt: serverTimestamp() });
    setSurvey({ demandMet: null, problemSolved: null, likedChat: null, rating: 0 });
    setActiveTicket(null);
    setActiveTab('atendimento');
  };

  // --- PDF GENERATOR (DESIGN PRO + BASE64 ALWAYS) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
    if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
    setIsGeneratingPdf(true);

    // ✅ para garantir base64 sempre:
    const FORCE_BASE64_URL = true;

    try {
      const code = generateVerificationCode();

      const docTitle =
        docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' :
        docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' :
        docType === 'historico' ? 'HISTÓRICO ESCOLAR' :
        'GUIA DE TRANSFERÊNCIA';

      // Data
      let modulesData: any[] = [];
      let courseData: any = {};
      if (opStudent.cursoInicial) {
        const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
        if (cSnap.exists()) courseData = cSnap.data();
        const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
        const mSnap = await getDocs(mQuery);
        modulesData = mSnap.docs.map(d => d.data());
      }

      const studentName = (opStudent.displayName || '').toUpperCase();
      const studentCpf  = opStudent.cpf || '---';
      const studentId   = opStudent.academicId || '---';
      const courseName  = (courseData.nome || opStudent.cursoInicial || 'TEOLOGIA').toUpperCase();

      const validationUrl = `${window.location.origin}?code=${code}`;
      const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 180 });

      // Assets to Base64 (logo & signatures)
      const loadAsset = async (url?: string) => {
        if(!url) return null;
        try { return await fetchAsDataURL(url); } catch { return null; }
      };

      const logoDataUrl = await loadAsset(schoolConfig.logoUrl);
      const directorSigDataUrl = await loadAsset(directorSignature || undefined);
      const secSigDataUrl = await loadAsset(secSignature || undefined);

      // Orientation: certificate landscape; others portrait
      const isCertificate = docType === 'conclusao';
      const docPdf = new jsPDF({
        orientation: isCertificate ? 'landscape' : 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const width = docPdf.internal.pageSize.getWidth();
      const height = docPdf.internal.pageSize.getHeight();

      // -------------------------
      // PAGE 1 (MAIN DOC)
      // -------------------------
      drawFrame(docPdf);
      drawTopBand(docPdf, schoolConfig, logoDataUrl, isCertificate ? "DIPLOMA / CERTIFICADO" : "DOCUMENTO OFICIAL");
      drawWatermark(docPdf, logoDataUrl);

      if (isCertificate) {
        // CERTIFICATE LAYOUT
        drawCertificateBadge(docPdf, "CERTIFICADO");

        // Big Title
        setText(docPdf, "times", "bold", 26, BRAND.primary);
        docPdf.text("CERTIFICADO DE CONCLUSÃO", width/2, 48, { align: "center" });

        setText(docPdf, "helvetica", "normal", 10, BRAND.muted);
        const subtitle = schoolConfig.cnpj ? `CNPJ: ${schoolConfig.cnpj}` : "Instituição de Ensino Teológico";
        docPdf.text(subtitle, width/2, 55, { align: "center" });

        // Student highlight block
        docPdf.setDrawColor(226,232,240);
        docPdf.setLineWidth(0.6);
        docPdf.roundedRect(22, 64, width - 44, 40, 3, 3);

        setText(docPdf, "helvetica", "bold", 9, BRAND.muted);
        docPdf.text("CERTIFICAMOS QUE", width/2, 74, { align: "center" });

        setText(docPdf, "times", "bold", 22, BRAND.primary);
        docPdf.text(studentName, width/2, 86, { align: "center" });

        setText(docPdf, "helvetica", "normal", 11, [15,23,42]);
        const body = `Concluiu com êxito o curso de ${courseName}, cumprindo integralmente a carga horária, os requisitos acadêmicos e as avaliações previstas no projeto pedagógico desta instituição.`;
        const bodyLines = docPdf.splitTextToSize(body, width - 60);
        docPdf.text(bodyLines, width/2, 98, { align: "center" });

        // Info grid (CPF / RA / Data)
        const dateStr = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });
        drawInfoGrid(docPdf, 22, 110, width - 44, [
          { label: "CPF", value: studentCpf },
          { label: "Matrícula (RA)", value: studentId },
          { label: "Data de Emissão", value: `São Paulo, ${dateStr}` }
        ]);

        // Signatures + footer validation
        drawSignaturesRow(docPdf, directorSigDataUrl, secSigDataUrl, "Diretoria Executiva", "Secretaria Geral");
        drawFooterValidation(docPdf, validationUrl, code, qrCodeDataUrl);

      } else {
        // DECLARAÇÃO / TRANSFERÊNCIA / HISTÓRICO (portrait clean)
        setText(docPdf, "times", "bold", 20, BRAND.primary);
        docPdf.text(docTitle, width/2, 36, { align: "center" });

        setText(docPdf, "helvetica", "normal", 9, BRAND.muted);
        const line2 = "Documento oficial emitido pela Secretaria Acadêmica";
        docPdf.text(line2, width/2, 42, { align: "center" });

        drawSectionTitle(docPdf, "Identificação do Aluno", 14, 55);
        drawInfoGrid(docPdf, 14, 58, width - 28, [
          { label: "Aluno(a)", value: studentName },
          { label: "CPF", value: studentCpf },
          { label: "Matrícula (RA)", value: studentId },
          { label: "Curso", value: courseName },
        ]);

        drawSectionTitle(docPdf, "Declaração", 14, 105);

        setText(docPdf, "times", "normal", 12, [15,23,42]);
        let textData = "";
        if (docType === 'matricula') {
          textData = `Declaramos, a quem possa interessar, que o(a) aluno(a) ${studentName}, inscrito(a) no CPF nº ${studentCpf} e matrícula ${studentId}, encontra-se regularmente MATRICULADO(A) no curso de ${courseName} desta instituição, frequentando as atividades letivas do presente período.`;
        } else if (docType === 'transferencia') {
          textData = `Atestamos a transferência do(a) discente ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, do curso de ${courseName}, estando apto(a) a prosseguir seus estudos na instituição de destino, conforme legislação vigente.`;
        } else { // historico
          textData = `Certificamos o Histórico Escolar do(a) aluno(a) ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, referente ao curso de ${courseName}, conforme detalhamento de disciplinas, notas e frequência apresentados na(s) página(s) subsequente(s).`;
        }

        const para = docPdf.splitTextToSize(textData, width - 28);
        docPdf.text(para, 14, 114);

        const dateStr = new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
        setText(docPdf, "times", "italic", 11, BRAND.muted);
        docPdf.text(`São Paulo, ${dateStr}.`, width - 14, 150, { align: "right" });

        drawSignaturesRow(docPdf, directorSigDataUrl, secSigDataUrl, "Diretoria Executiva", "Secretaria Geral");
        drawFooterValidation(docPdf, validationUrl, code, qrCodeDataUrl);

        // If HISTÓRICO: add page 2 with table
        if (docType === "historico") {
          docPdf.addPage();
          const w2 = docPdf.internal.pageSize.getWidth();
          const h2 = docPdf.internal.pageSize.getHeight();

          drawFrame(docPdf);
          drawTopBand(docPdf, schoolConfig, logoDataUrl, "HISTÓRICO ESCOLAR");
          drawWatermark(docPdf, logoDataUrl);

          setText(docPdf, "times", "bold", 16, BRAND.primary);
          docPdf.text("HISTÓRICO ESCOLAR - DISCIPLINAS", w2/2, 34, { align: "center" });

          setText(docPdf, "helvetica", "normal", 9, BRAND.muted);
          docPdf.text(`Aluno: ${studentName} | RA: ${studentId}`, w2/2, 40, { align: "center" });

          const tableBody = modulesData.length > 0
            ? modulesData.map((m: any) => [
                String(m.title || "Módulo"),
                String(m.cargaHoraria || "20h"),
                String(m.frequencia || "100%"),
                String(m.nota || "10.0"),
                String(m.status || "APROVADO"),
              ])
            : [
                ["Teologia Sistemática", "40h", "100%", "10.0", "APROVADO"],
                ["Hermenêutica", "30h", "100%", "9.5", "APROVADO"],
              ];

          autoTable(docPdf, {
            startY: 50,
            head: [["Disciplina / Módulo", "C.H.", "Freq.", "Nota", "Situação"]],
            body: tableBody,
            theme: "grid",
            headStyles: { fillColor: BRAND.primary, textColor: 255, fontStyle: "bold" },
            styles: { fontSize: 9, font: "helvetica", cellPadding: 2.5 },
            margin: { left: 14, right: 14 },
          });

          drawFooterValidation(docPdf, validationUrl, code, qrCodeDataUrl);
        }
      }

      // -------------------------
      // OUTPUTS (BLOB + BASE64)
      // -------------------------
      const pdfBlob = docPdf.output('blob');
      const pdfBase64 = docPdf.output('datauristring'); // ✅ mantém no formato data:application/pdf;base64,...

      // feedback imediato
      const localUrl = URL.createObjectURL(pdfBlob);
      window.open(localUrl, '_blank');

      // -------------------------
      // SAVE (Storage try + Firestore base64)
      // -------------------------
      const cleanTitle = safeName(`${docTitle}-${opStudent.displayName || "aluno"}.pdf`);
      const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;

      let uploadResult: any = { ok: false, url: "", storagePath: null, fallbackReason: "forced_base64" };

      // Se você quiser TENTAR upload, mantenha:
      try {
        uploadResult = await uploadBlobToStorage(pdfBlob, storagePath, 'application/pdf');
      } catch (e) {
        uploadResult = { ok: false, url: "", storagePath: null, fallbackReason: "upload_error" };
      }

      // ✅ URL final: sempre base64 se FORCE_BASE64_URL=true
      const finalUrl = FORCE_BASE64_URL ? pdfBase64 : (uploadResult.ok ? uploadResult.url : pdfBase64);

      const status =
        FORCE_BASE64_URL ? "stored_base64" :
        (uploadResult.ok ? "uploaded" : `fallback_base64_${uploadResult.fallbackReason}`);

      await addDoc(collection(db, 'secretaria_arquivos'), {
        name: `${docTitle} - ${opStudent.displayName}.pdf`,
        type: 'file',
        mimeType: 'application/pdf',
        url: finalUrl,                 // ✅ base64 garantido se FORCE_BASE64_URL
        storagePath: uploadResult.ok ? uploadResult.storagePath : null,
        storageStatus: status,
        parentId: 'root',
        createdAt: serverTimestamp(),
        createdBy: user.uid,
        studentId: opStudent.uid,
        docType: docType,
        docData: {
          code,
          title: docTitle,
          date: new Date().toISOString(),
          student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
          courseData,
          modulesData,
        }
      });

      if (!uploadResult.ok) {
        console.warn("Upload falhou (ou foi ignorado). Documento preservado em Base64 no Firestore.");
      }

    } catch (e: any) {
      console.error(e);
      alert("Erro na geração do PDF: " + (e.message || "Erro desconhecido"));
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  // --- RENDER ---
  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
