Perfeito — vamos **organizar o layout** e dar **identidade visual de escola** (estilo “certificado premium” como nas suas imagens), e ao mesmo tempo **garantir que o PDF fique salvo em Base64 no Firestore** (inclusive quando o upload falhar). O seu certificado atual (exemplo do PDF gerado) está com hierarquia fraca, muito “bloco” e pouco “certificado” (título, brasão, moldura, destaque do nome e do curso, rodapé de validação). 

Abaixo está um **upgrade direto** no seu gerador `generateLegalPDF`, com:

* **Moldura premium (dourado + marinho)** + faixa superior;
* **Nome do aluno e curso com destaque**;
* **Blocos de dados** (CPF/RA/data/carga horária) bem distribuídos;
* **Assinaturas alinhadas**;
* **QR + bloco de validação** padronizado;
* **Histórico** com cabeçalho forte e tabela mais legível;
* **Persistência em Base64** (com opção de “chunk” pra não estourar limite do Firestore).

> ⚠️ Importante (realista): **Firestore tem limite ~1 MiB por documento**. Um PDF em Base64 pode estourar isso facilmente. Por isso deixei o salvamento **em chunks** (subcoleção) quando necessário. Você continua “mantendo base64” de forma segura.

---

## 1) Cole estes HELPERS (substituem seus `drawPageBorder/drawHeader` e adicionam layout premium)

> Cole **acima** do componente (na área de helpers), mantendo seus imports atuais.

```ts
// =====================
// PDF DESIGN SYSTEM
// =====================
const PDF_THEME = {
  navy: [15, 23, 42] as [number, number, number],      // slate-900
  slate: [71, 85, 105] as [number, number, number],    // slate-600
  light: [248, 250, 252] as [number, number, number],  // slate-50
  line: [226, 232, 240] as [number, number, number],   // slate-200
  gold: [184, 134, 11] as [number, number, number],    // "goldenrod"
  gold2: [212, 175, 55] as [number, number, number],   // metallic-ish
};

const mm = (n: number) => n; // só pra legibilidade

const safeText = (v: any) => (v ?? "").toString().trim();

const drawDoubleFrame = (doc: any) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();

  doc.setDrawColor(...PDF_THEME.gold2);
  doc.setLineWidth(1.0);
  doc.rect(6, 6, w - 12, h - 12);

  doc.setDrawColor(...PDF_THEME.line);
  doc.setLineWidth(0.4);
  doc.rect(8, 8, w - 16, h - 16);

  // Cantos (mini detalhe)
  doc.setDrawColor(...PDF_THEME.gold);
  doc.setLineWidth(0.6);
  doc.line(10, 14, 22, 14);
  doc.line(10, 14, 10, 26);

  doc.line(w - 10, 14, w - 22, 14);
  doc.line(w - 10, 14, w - 10, 26);

  doc.line(10, h - 14, 22, h - 14);
  doc.line(10, h - 14, 10, h - 26);

  doc.line(w - 10, h - 14, w - 22, h - 14);
  doc.line(w - 10, h - 14, w - 10, h - 26);
};

const drawTopBanner = (doc: any, schoolName: string, subtitle: string, logoDataUrl?: string | null) => {
  const w = doc.internal.pageSize.getWidth();

  // Faixa superior
  doc.setFillColor(...PDF_THEME.navy);
  doc.rect(8, 8, w - 16, 20, "F");

  // Linha dourada
  doc.setDrawColor(...PDF_THEME.gold2);
  doc.setLineWidth(0.6);
  doc.line(8, 28, w - 8, 28);

  // Logo (esquerda)
  if (logoDataUrl) {
    try {
      doc.addImage(logoDataUrl, "PNG", 12, 10.5, 14, 14);
    } catch {}
  }

  // Nome da escola
  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text(schoolName.toUpperCase(), w / 2, 17, { align: "center" });

  // Subtítulo
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(230, 230, 230);
  doc.text(subtitle, w / 2, 23, { align: "center" });
};

const drawCertificateTitle = (doc: any, title: string, tag?: string) => {
  const w = doc.internal.pageSize.getWidth();

  // Tag (pílula)
  if (tag) {
    const pillW = 42;
    doc.setFillColor(...PDF_THEME.navy);
    doc.roundedRect(w - 8 - pillW - 8, 36, pillW, 10, 3, 3, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.setTextColor(255, 255, 255);
    doc.text(tag.toUpperCase(), w - 8 - 8 - pillW / 2, 42.8, { align: "center" });
  }

  // Título
  doc.setFont("times", "bold");
  doc.setFontSize(26);
  doc.setTextColor(...PDF_THEME.navy);
  doc.text(title.toUpperCase(), w / 2, 54, { align: "center" });

  // Filete dourado
  doc.setDrawColor(...PDF_THEME.gold2);
  doc.setLineWidth(0.7);
  doc.line(w / 2 - 55, 58, w / 2 + 55, 58);
};

const drawWatermark = (doc: any, watermarkDataUrl?: string | null) => {
  if (!watermarkDataUrl) return;
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  // jsPDF v2.5 tem GState; se falhar, ignora.
  try {
    const gState = (doc as any).GState ? new (doc as any).GState({ opacity: 0.06 }) : null;
    if (gState && (doc as any).setGState) (doc as any).setGState(gState);
    doc.addImage(watermarkDataUrl, "PNG", w / 2 - 45, h / 2 - 45, 90, 90);
    // reset (tenta)
    if ((doc as any).setGState) (doc as any).setGState(new (doc as any).GState({ opacity: 1 }));
  } catch {}
};

const drawInfoGrid = (doc: any, x: number, y: number, w: number, items: { label: string; value: string }[]) => {
  // container
  doc.setFillColor(...PDF_THEME.light);
  doc.setDrawColor(...PDF_THEME.line);
  doc.setLineWidth(0.4);
  doc.roundedRect(x, y, w, 26, 3, 3, "FD");

  const colW = w / 2;
  const rowY1 = y + 8;
  const rowY2 = y + 19;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(...PDF_THEME.slate);

  // 4 campos (2x2)
  const a = items[0] ?? { label: "", value: "" };
  const b = items[1] ?? { label: "", value: "" };
  const c = items[2] ?? { label: "", value: "" };
  const d = items[3] ?? { label: "", value: "" };

  const drawCell = (cx: number, cy: number, it: { label: string; value: string }) => {
    doc.text(it.label.toUpperCase(), cx, cy);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(...PDF_THEME.navy);
    doc.text(it.value, cx, cy + 5);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.setTextColor(...PDF_THEME.slate);
  };

  drawCell(x + 6, rowY1, a);
  drawCell(x + 6 + colW, rowY1, b);
  drawCell(x + 6, rowY2, c);
  drawCell(x + 6 + colW, rowY2, d);
};

const drawSignaturesRow = (
  doc: any,
  directorSig?: string | null,
  secSig?: string | null,
  leftLabel = "DIRETORIA EXECUTIVA",
  rightLabel = "SECRETARIA GERAL"
) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  const margin = 18;
  const yLine = h - 30;

  // linhas
  doc.setDrawColor(...PDF_THEME.line);
  doc.setLineWidth(0.6);
  doc.line(margin, yLine, w / 2 - 10, yLine);
  doc.line(w / 2 + 10, yLine, w - margin, yLine);

  // assinaturas (imagem acima da linha)
  if (directorSig) {
    try { doc.addImage(directorSig, "PNG", margin + 10, yLine - 16, 38, 14); } catch {}
  }
  if (secSig) {
    try { doc.addImage(secSig, "PNG", w - margin - 48, yLine - 16, 38, 14); } catch {}
  }

  // labels
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8.5);
  doc.setTextColor(...PDF_THEME.slate);
  doc.text(leftLabel, (margin + (w / 2 - 10)) / 2, yLine + 6, { align: "center" });
  doc.text(rightLabel, ((w / 2 + 10) + (w - margin)) / 2, yLine + 6, { align: "center" });
};

const drawValidationBlock = (doc: any, code: string, url: string, qrDataUrl: string) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();

  const boxW = 70;
  const boxH = 26;
  const x = 18;
  const y = h - 26 - 18;

  doc.setFillColor(255, 255, 255);
  doc.setDrawColor(...PDF_THEME.line);
  doc.setLineWidth(0.4);
  doc.roundedRect(x, y, boxW, boxH, 3, 3, "FD");

  // QR
  try {
    doc.addImage(qrDataUrl, "PNG", x + 3, y + 3, 20, 20);
  } catch {}

  // textos
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(...PDF_THEME.navy);
  doc.text("VALIDAÇÃO DIGITAL", x + 26, y + 8);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(...PDF_THEME.slate);
  doc.text(`Código: ${code}`, x + 26, y + 13);

  const shortUrl = url.length > 42 ? url.slice(0, 42) + "..." : url;
  doc.text(shortUrl, x + 26, y + 18);
  doc.text("Documento verificável via QR Code.", x + 26, y + 23);
};

// =====================
// BASE64 STORAGE (COM CHUNKS)
// =====================
const dataUriToBase64 = (dataUri: string) => {
  const idx = dataUri.indexOf("base64,");
  return idx >= 0 ? dataUri.substring(idx + 7) : dataUri;
};

const splitIntoChunks = (str: string, chunkSize = 800_000) => {
  const out: string[] = [];
  for (let i = 0; i < str.length; i += chunkSize) out.push(str.slice(i, i + chunkSize));
  return out;
};
