```ts
const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
  if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
  setIsGeneratingPdf(true);

  try {
    const code = generateVerificationCode();

    const docTitle =
      docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' :
      docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' :
      docType === 'historico' ? 'HISTÓRICO ESCOLAR' :
      'GUIA DE TRANSFERÊNCIA';

    // ======= Dados acadêmicos =======
    let modulesData: any[] = [];
    let courseData: any = {};
    if (opStudent.cursoInicial) {
      const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
      if (cSnap.exists()) courseData = cSnap.data();
      const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
      const mSnap = await getDocs(mQuery);
      modulesData = mSnap.docs.map(d => ({ id: d.id, ...d.data() }));
    }

    const schoolName = safeText(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD");
    const cnpj = safeText(schoolConfig.cnpj || "");
    const subtitle = cnpj ? `CNPJ: ${cnpj}` : "Instituição de Ensino Teológico";
    const validationUrl = `${window.location.origin}?code=${code}`;
    const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 120 });

    const loadAsset = async (url?: string) => {
      if (!url) return null;
      try { return await fetchAsDataURL(url); } catch { return null; }
    };

    const logoDataUrl = await loadAsset(schoolConfig.logoUrl);
    const directorSigDataUrl = await loadAsset(directorSignature || undefined);
    const secSigDataUrl = await loadAsset(secSignature || undefined);

    // ======= PDF =======
    const isCertificate = docType === "conclusao";
    const docPdf = new jsPDF({
      orientation: isCertificate ? 'landscape' : 'portrait',
      unit: 'mm', format: 'a4'
    });

    const width = docPdf.internal.pageSize.getWidth();
    const height = docPdf.internal.pageSize.getHeight();

    // ==========================================
    // PÁGINA 1 (CERTIFICADO/DECLARAÇÃO/TRANSFERÊNCIA)
    // ==========================================
    drawDoubleFrame(docPdf);
    drawTopBanner(docPdf, schoolName, subtitle, logoDataUrl);
    drawWatermark(docPdf, logoDataUrl); // watermark leve do logo (se existir)
    drawCertificateTitle(docPdf, docTitle, isCertificate ? "DIPLOMA / CERTIFICADO" : "DOCUMENTO");

    const studentName = safeText(opStudent.displayName).toUpperCase();
    const studentCpf = safeText(opStudent.cpf || '---');
    const studentId = safeText(opStudent.academicId || '---');
    const courseName = safeText(courseData.nome || opStudent.cursoInicial || 'TEOLOGIA').toUpperCase();

    // Texto “com cara de certificado”
    let bodyText = "";
    if (docType === 'conclusao') {
      bodyText =
        `O Diretor desta Instituição certifica, para os devidos fins, que ${studentName}, ` +
        `portador(a) do CPF nº ${studentCpf}, matrícula acadêmica ${studentId}, ` +
        `CONCLUIU com êxito o curso de ${courseName}, cumprindo integralmente a carga horária, ` +
        `os requisitos acadêmicos e as avaliações previstas no projeto pedagógico desta instituição.`;
    } else if (docType === 'matricula') {
      bodyText =
        `Declaramos, a quem possa interessar, que ${studentName}, inscrito(a) no CPF nº ${studentCpf} ` +
        `e matrícula ${studentId}, encontra-se regularmente MATRICULADO(A) no curso de ${courseName}, ` +
        `frequentando as atividades acadêmicas do presente período.`;
    } else if (docType === 'transferencia') {
      bodyText =
        `Atestamos a transferência do(a) discente ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, ` +
        `vinculado(a) ao curso de ${courseName}, estando apto(a) a prosseguir seus estudos na instituição de destino, ` +
        `conforme normativas vigentes.`;
    } else {
      bodyText =
        `Certificamos o Histórico Escolar do(a) aluno(a) ${studentName}, CPF ${studentCpf}, matrícula ${studentId}, ` +
        `referente ao curso de ${courseName}, conforme detalhamento acadêmico apresentado.`;
    }

    // Bloco central (nome e texto)
    const marginX = 22;
    const contentTop = 66;

    // “CERTIFICAMOS QUE”
    docPdf.setFont("helvetica", "bold");
    docPdf.setFontSize(10);
    docPdf.setTextColor(...PDF_THEME.slate);
    docPdf.text("CERTIFICAMOS QUE", width / 2, contentTop + 8, { align: "center" });

    // Nome do aluno (destaque)
    docPdf.setFont("times", "bold");
    docPdf.setFontSize(isCertificate ? 30 : 22);
    docPdf.setTextColor(...PDF_THEME.navy);
    docPdf.text(studentName || "ALUNO(A)", width / 2, contentTop + 22, { align: "center" });

    // Texto do corpo (justificado via split)
    docPdf.setFont("times", "normal");
    docPdf.setFontSize(13);
    docPdf.setTextColor(20, 20, 20);
    const bodyLines = docPdf.splitTextToSize(bodyText, width - (marginX * 2));
