    // Só inclui p/ "historico" ou "conclusao" (como anexo elegante)
    // ==========================================
    const includeSecondPage = (docType === "historico" || docType === "conclusao");
    if (includeSecondPage) {
      docPdf.addPage();
      const w2 = docPdf.internal.pageSize.getWidth();
      const h2 = docPdf.internal.pageSize.getHeight();

      drawDoubleFrame(docPdf);
      drawTopBanner(docPdf, schoolName, "HISTÓRICO ESCOLAR E VALIDAÇÃO", logoDataUrl);

      docPdf.setFont("times", "bold");
      docPdf.setFontSize(18);
      docPdf.setTextColor(...PDF_THEME.navy);
      docPdf.text("HISTÓRICO ESCOLAR", w2 / 2, 45, { align: "center" });

      // mini ficha do aluno
      docPdf.setFont("helvetica", "normal");
      docPdf.setFontSize(10);
      docPdf.setTextColor(...PDF_THEME.slate);
      docPdf.text(`Aluno(a): ${studentName}`, 22, 56);
      docPdf.text(`CPF: ${studentCpf}   |   RA: ${studentId}`, 22, 62);
      docPdf.text(`Curso: ${courseName}`, 22, 68);

      // tabela (mais bonita)
      const tableBody =
        modulesData.length > 0
          ? modulesData.map((m: any) => [
              safeText(m.title || m.nome || "Módulo"),
              safeText(m.ch || m.cargaHoraria || "20h"),
              safeText(m.frequencia || "100%"),
              safeText(m.nota || "10.0"),
              safeText(m.status || "APROVADO"),
            ])
          : [
              ["Teologia Sistemática", "40h", "100%", "10.0", "APROVADO"],
              ["Hermenêutica", "30h", "100%", "9.5", "APROVADO"],
            ];

      autoTable(docPdf, {
        startY: 76,
        head: [["Disciplina / Módulo", "C.H.", "Freq.", "Nota", "Situação"]],
        body: tableBody,
        theme: "grid",
        headStyles: { fillColor: PDF_THEME.navy as any, textColor: 255, fontStyle: "bold", halign: "center" },
        styles: { fontSize: 9.5, font: "helvetica", cellPadding: 2.2, lineColor: PDF_THEME.line as any },
        columnStyles: {
          0: { cellWidth: 110 },
          1: { halign: "center", cellWidth: 18 },
          2: { halign: "center", cellWidth: 18 },
          3: { halign: "center", cellWidth: 18 },
          4: { halign: "center", cellWidth: 24 },
        },
        margin: { left: 22, right: 22 },
      });

      // validação no rodapé da página 2 também (fica “oficial”)
      drawValidationBlock(docPdf, code, validationUrl, qrCodeDataUrl);
    }

    // ==========================================
    // BASE64: sempre gerar e salvar
    // ==========================================
    const pdfBlob = docPdf.output("blob");
    const dataUri = docPdf.output("datauristring"); // data:application/pdf;base64,...
    const base64 = dataUriToBase64(dataUri);

    // feedback imediato
    const localUrl = URL.createObjectURL(pdfBlob);
    window.open(localUrl, "_blank");

    // tenta storage (opcional), mas mantém base64 no Firestore SEMPRE
    const cleanTitle = safeName(`${docTitle}-${opStudent.displayName || "aluno"}.pdf`);
    const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;
    const uploadResult = await uploadBlobToStorage(pdfBlob, storagePath, "application/pdf");

    // salva registro principal
    const docRef = await addDoc(collection(db, "secretaria_arquivos"), {
      name: `${docTitle} - ${opStudent.displayName}.pdf`,
      type: "file",
      mimeType: "application/pdf",

      // Importante: manter base64 como fonte de verdade
      url: `data:application/pdf;base64,${base64}`, // leitura direta quando couber
      base64Chunked: false,

      // se quiser guardar URL do storage também:
      storageUrl: uploadResult.ok ? uploadResult.url : null,
      storagePath: uploadResult.ok ? uploadResult.storagePath : null,
      storageStatus: uploadResult.ok ? "uploaded_plus_base64" : `fallback_base64_${uploadResult.fallbackReason}`,

      parentId: "root",
      createdAt: serverTimestamp(),
      createdBy: user.uid,
      studentId: opStudent.uid,
      docType,
      docData: {
        code,
        title: docTitle,
        date: new Date().toISOString(),
        student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
        courseData,
        modulesData,
      },
    });

    // Se base64 for grande, converte para chunks e remove url grande (evita estourar 1MiB)
    // Estratégia: se passar ~900k chars (bem conservador), usa chunks.
    if (base64.length > 900_000) {
      const chunks = splitIntoChunks(base64, 800_000);

      // marca doc como chunkado e remove url (evita documento gigante)
      await updateDoc(doc(db, "secretaria_arquivos", docRef.id), {
        url: null,
        base64Chunked: true,
        base64BytesApprox: base64.length,
        chunksCount: chunks.length,
      });

      // grava chunks na subcoleção
      // (cada chunk vira um doc pequeno)
      for (let i = 0; i < chunks.length; i++) {
        await setDoc(doc(db, "secretaria_arquivos", docRef.id, "chunks", String(i)), {
          index: i,
          data: chunks[i],
          createdAt: serverTimestamp(),
        });
      }
    }

    if (!uploadResult.ok) {
      console.warn("Upload falhou (provável CORS). Documento ficou garantido em Base64 no Firestore.");
    }
  } catch (e: any) {
    console.error(e);
    alert("Erro na geração do PDF: " + (e?.message || "Erro desconhecido"));
  } finally {
    setIsGeneratingPdf(false);
  }
};
