## 2) Atualize o `viewFile` para suportar Base64 “chunkado” (sem URL do Storage)

> Substitua seu `viewFile` por este (mantém abertura por `data:` e ainda funciona com `http`, mas agora também reconstrói base64 via chunks):

```ts
const viewFile = async (file: any) => {
  if (!file) return;

  // 1) URL direta (storage/http/data:)
  if (file.url) {
    const newWindow = window.open();
    if (!newWindow) return alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");

    if (file.url.startsWith("data:")) {
      newWindow.document.write(`<iframe width='100%' height='100%' style='border:none;' src='${file.url}'></iframe>`);
      newWindow.document.title = file.name || "Documento";
      return;
    }
    newWindow.location.href = file.url;
    return;
  }

  // 2) Reconstrução via chunks (Firestore subcollection)
  if (file.base64Chunked === true) {
    try {
      const chunksSnap = await getDocs(
        query(
          collection(db, "secretaria_arquivos", file.id, "chunks"),
          orderBy("index", "asc")
        )
      );
      if (chunksSnap.empty) return alert("Não foi possível reconstruir o arquivo (chunks vazios).");

      const base64 = chunksSnap.docs.map(d => (d.data() as any).data || "").join("");
      const dataUri = `data:application/pdf;base64,${base64}`;

      const newWindow = window.open();
      if (!newWindow) return alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");

      newWindow.document.write(`<iframe width='100%' height='100%' style='border:none;' src='${dataUri}'></iframe>`);
      newWindow.document.title = file.name || "Documento";
      return;
    } catch (e) {
      console.error(e);
      return alert("Erro ao abrir documento em base64 (chunks).");
    }
  }

  alert("Erro: Arquivo sem URL válida para visualização.");
};
```

