      drawDoubleFrame(docPdf);
      drawTopBanner(docPdf, schoolName, subtitle, logoDataUrl);
      drawWatermark(docPdf, logoDataUrl);

      if (isCertificate) {
        // CERTIFICATE LAYOUT
        drawCertificateTitle(docPdf, docTitle, "DIPLOMA / CERTIFICADO");
        drawCertificateBadge(docPdf, "CERTIFICADO");

        // "CERTIFICAMOS QUE"
