// =====================
// CLEAN PDF DESIGN SYSTEM
// =====================
const PDF_THEME = {
  textMain: [30, 41, 59] as [number, number, number],   // slate-900 (Dark)
  textSec: [100, 116, 139] as [number, number, number], // slate-500 (Gray)
  accent: [184, 134, 11] as [number, number, number],   // Gold/Bronze lines
  lineColor: [203, 213, 225] as [number, number, number]// Light gray lines
};

const safeText = (v: any) => (v ?? "").toString().trim();

// 1. Moldura Clássica e Limpa (Com Margem de Segurança)
const drawClassicBorder = (doc: any) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  const margin = 5; // 5mm da borda do papel

  // Linha Externa (Fina)
  doc.setDrawColor(...PDF_THEME.textMain);
  doc.setLineWidth(0.3);
  doc.rect(margin, margin, w - (margin * 2), h - (margin * 2));

  // Linha Interna (Dourada/Accent - Mais grossa)
  doc.setDrawColor(...PDF_THEME.accent);
  doc.setLineWidth(0.8);
  doc.rect(margin + 1.5, margin + 1.5, w - (margin * 2) - 3, h - (margin * 2) - 3);
};

// 2. Cabeçalho Limpo (Sem faixa azul, logo ao lado do texto)
const drawCleanHeader = (doc: any, title: string, logoDataUrl?: string | null) => {
  const w = doc.internal.pageSize.getWidth();
  const yStart = 20; // Começa um pouco abaixo da moldura

  // Logo (Esquerda do bloco central ou alinhado)
  // Vamos centralizar o bloco [Logo + Título] para ficar elegante

  doc.setFont("times", "bold");
  doc.setFontSize(22);
  doc.setTextColor(...PDF_THEME.textMain);

  // Se tiver logo, desenha
  if (logoDataUrl) {
    const logoSize = 18;
    // Posição: Título centralizado, Logo à esquerda do título com um padding
    const textWidth = doc.getTextWidth(title.toUpperCase());
    const totalWidth = logoSize + 4 + textWidth; // 4mm gap
    const startX = (w - totalWidth) / 2;

    try {
      doc.addImage(logoDataUrl, "PNG", startX, yStart - 6, logoSize, logoSize);
    } catch {}

    doc.text(title.toUpperCase(), startX + logoSize + 4, yStart + 6);
  } else {
    // Sem logo, só texto centralizado
    doc.text(title.toUpperCase(), w / 2, yStart + 6, { align: "center" });
  }

  // Linha separadora sutil abaixo do cabeçalho
  doc.setDrawColor(...PDF_THEME.lineColor);
  doc.setLineWidth(0.2);
  doc.line(20, yStart + 16, w - 20, yStart + 16);
};

// 3. Marca d'água centralizada e sutil
const drawWatermark = (doc: any, logoDataUrl?: string | null) => {
  if (!logoDataUrl) return;
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  try {
    const gState = (doc as any).GState ? new (doc as any).GState({ opacity: 0.04 }) : null;
    if (gState && (doc as any).setGState) (doc as any).setGState(gState);
    const size = 100;
    doc.addImage(logoDataUrl, "PNG", (w/2) - (size/2), (h/2) - (size/2), size, size);
    if ((doc as any).setGState) (doc as any).setGState(new (doc as any).GState({ opacity: 1 }));
  } catch {}
};

// 4. Bloco de Dados do Aluno (Texto Limpo, sem caixas)
const drawStudentDataClean = (doc: any, y: number, student: any, courseName: string) => {
  const w = doc.internal.pageSize.getWidth();
  const marginX = 20;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(...PDF_THEME.textSec);
  doc.text("DADOS DO DISCENTE", marginX, y);

  const startY = y + 6;
  const lineHeight = 7;

  // Helper para desenhar campo: Rótulo (Bold Gray) + Valor (Bold Dark)
  const drawField = (label: string, value: string, x: number, lineY: number) => {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(...PDF_THEME.textSec);
    doc.text(label.toUpperCase() + ":", x, lineY);

    const labelWidth = doc.getTextWidth(label.toUpperCase() + ":");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(...PDF_THEME.textMain);
    doc.text(value.toUpperCase(), x + labelWidth + 2, lineY);
  };

  // Linha 1: Nome
  drawField("Nome Civil", safeText(student.displayName), marginX, startY);

  // Linha 2: CPF e RA
  drawField("CPF", safeText(student.cpf || "---"), marginX, startY + lineHeight);
  drawField("Matrícula (RA)", safeText(student.academicId || "---"), marginX + 80, startY + lineHeight); // Offset para 2a coluna

  // Linha 3: Curso
  drawField("Curso", courseName, marginX, startY + (lineHeight * 2));

  return startY + (lineHeight * 3); // Retorna Y final
};

// 5. Rodapé Seguro (Assinaturas + QR + Nome Escola)
// Garante que nada saia da moldura inferior
const drawSecureFooter = (doc: any, schoolName: string, validationUrl: string, code: string, qrDataUrl: string, directorSig: any, secSig: any) => {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  const margin = 5; // igual moldura
  const bottomSafeLimit = h - margin - 2; // 2mm de respiro da moldura inferior

  // 1. Nome da Escola (Bem no rodapé)
  doc.setFont("times", "bold");
  doc.setFontSize(9);
  doc.setTextColor(...PDF_THEME.textMain);
  doc.text(schoolName.toUpperCase(), w / 2, bottomSafeLimit - 5, { align: "center" });

  // 2. QR Code e Validação (Lado Esquerdo Inferior)
  const qrSize = 18;
  const qrY = bottomSafeLimit - 12 - qrSize;
  const qrX = 15; // Margem lateral conteúdo

  try {
    doc.addImage(qrDataUrl, "PNG", qrX, qrY, qrSize, qrSize);
  } catch {}

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7);
  doc.setTextColor(...PDF_THEME.textMain);
  doc.text("VALIDAÇÃO DIGITAL", qrX + qrSize + 3, qrY + 5);

  doc.setFont("helvetica", "normal");
  doc.setTextColor(...PDF_THEME.textSec);
  doc.text(`Cód: ${code}`, qrX + qrSize + 3, qrY + 9);
  doc.text("Verifique a autenticidade via QR Code", qrX + qrSize + 3, qrY + 14);

  // 3. Assinaturas (Centralizadas/Alinhadas acima do rodapé)
  const sigY = qrY - 15; // Espaço acima do QR
  const sigWidth = 40;
  const sigHeight = 15;

  // Linhas das assinaturas
  doc.setDrawColor(...PDF_THEME.textSec);
  doc.setLineWidth(0.2);

  // Assinatura 1 (Esquerda/Centro-Esq)
  const xSig1 = (w / 2) - sigWidth - 15;
  if (directorSig) {
    try { doc.addImage(directorSig, "PNG", xSig1 + 5, sigY - sigHeight + 2, sigWidth - 10, sigHeight - 2); } catch {}
  }
  doc.line(xSig1, sigY, xSig1 + sigWidth, sigY);
  doc.text("DIRETORIA EXECUTIVA", xSig1 + (sigWidth/2), sigY + 4, { align: "center" });

  // Assinatura 2 (Direita/Centro-Dir)
  const xSig2 = (w / 2) + 15;
  if (secSig) {
    try { doc.addImage(secSig, "PNG", xSig2 + 5, sigY - sigHeight + 2, sigWidth - 10, sigHeight - 2); } catch {}
  }
  doc.line(xSig2, sigY, xSig2 + sigWidth, sigY);
  doc.text("SECRETARIA GERAL", xSig2 + (sigWidth/2), sigY + 4, { align: "center" });
};

// =====================
// BASE64 STORAGE
// =====================
const dataUriToBase64 = (dataUri: string) => {
  const idx = dataUri.indexOf("base64,");
  return idx >= 0 ? dataUri.substring(idx + 7) : dataUri;
};

const splitIntoChunks = (str: string, chunkSize = 800_000) => {
  const out: string[] = [];
  for (let i = 0; i < str.length; i += chunkSize) out.push(str.slice(i, i + chunkSize));
  return out;
};

const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewFile = async (file: any) => {
  if (!file) return;
  if (file.url) {
    const newWindow = window.open();
    if (!newWindow) return alert("Pop-up bloqueado. Permita pop-ups.");
    if (file.url.startsWith("data:")) {
      newWindow.document.write(`<iframe width='100%' height='100%' style='border:none;' src='${file.url}'></iframe>`);
      newWindow.document.title = file.name || "Documento";
      return;
    }
    newWindow.location.href = file.url;
    return;
  }
  if (file.base64Chunked === true) {
    try {
      const chunksSnap = await getDocs(query(collection(db, "secretaria_arquivos", file.id, "chunks"), orderBy("index", "asc")));
      if (chunksSnap.empty) return alert("Erro: Chunks vazios.");
      const base64 = chunksSnap.docs.map(d => (d.data() as any).data || "").join("");
      const dataUri = `data:application/pdf;base64,${base64}`;
      const newWindow = window.open();
      if (!newWindow) return alert("Pop-up bloqueado.");
      newWindow.document.write(`<iframe width='100%' height='100%' style='border:none;' src='${dataUri}'></iframe>`);
      newWindow.document.title = file.name || "Documento";
      return;
    } catch (e) { return alert("Erro ao reconstruir arquivo."); }
  }
  alert("Erro: Arquivo sem URL.");
};

