  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]); 
  const [chatMessage, setChatMessage] = useState('');
  const [secSignature, setSecSignature] = useState<string | null>(null); 
  const [directorSignature, setDirectorSignature] = useState<string | null>(null); 
  const [schoolConfig, setSchoolConfig] = useState<any>({});
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const [opStudent, setOpStudent] = useState<any>(null);
  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);
  const [timerDisplay, setTimerDisplay] = useState<string>('');
  const [survey, setSurvey] = useState({ demandMet: null as boolean|null, problemSolved: null as boolean|null, likedChat: null as boolean|null, rating: 0 });
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) { const updated = t.find((x: any) => x.id === activeTicket.id); if (updated) setActiveTicket(updated); }
    });
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    getDocs(query(collection(db, 'users'), where('role', '==', 'diretor'))).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });
    getDoc(doc(db, "system_settings", "main_config")).then((s) => { if (s.exists()) setSchoolConfig((s.data() as any).schoolConfig || {}); });
    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => { setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() }))); setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100); });
  }, [activeTicket]);

  useEffect(() => {
    let interval: any;
    if (activeTicket && activeTicket.status === 'Pendente') {
        interval = setInterval(async () => {
            const now = Date.now();
            const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : Date.now();
            const diff = now - created;
            const limit = 5 * 60 * 1000;
            if (diff >= limit) {
                const hasTimeoutMsg = messages.some((m: any) => m.text.includes("todos os atendentes"));
                if (!hasTimeoutMsg) {
                    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                        text: "Infelizmente, todos os atendentes estão ocupados. Sua solicitação foi registrada e entraremos em contato.",
                        sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
                    });
                    await updateDoc(doc(db, 'tickets', activeTicket.id), {
                        status: 'Encaminhado', lastMessage: "Timeout - Encaminhado", updatedAt: serverTimestamp()
                    });
                }
                setTimerDisplay("Tempo esgotado");
            } else {
                const remaining = Math.ceil((limit - diff) / 1000);
                const mins = Math.floor(remaining / 60);
                const secs = remaining % 60;
                setTimerDisplay(`${mins}:${secs.toString().padStart(2, '0')}`);
            }
        }, 1000);
    } else { setTimerDisplay(''); }
    return () => clearInterval(interval);
  }, [activeTicket, messages]);

  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
    if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
    setIsGeneratingPdf(true);
    const FORCE_BASE64_URL = true;

    try {
      const code = generateVerificationCode();
      // Define Title
      const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

      // Load Data
      let modulesData: any[] = [];
      let courseData: any = {};
      if (opStudent.cursoInicial) {
        const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
        if (cSnap.exists()) courseData = cSnap.data();
        const mSnap = await getDocs(query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial)));
        modulesData = mSnap.docs.map(d => ({ id: d.id, ...d.data() }));
      }

      const schoolName = safeText(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD");
      const validationUrl = `${window.location.origin}/verificar?code=${code}`;
      const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 0, width: 150 });
      const loadAsset = async (url?: string) => { if (!url) return null; try { return await fetchAsDataURL(url); } catch { return null; } };
      const logoDataUrl = await loadAsset(schoolConfig.logoUrl);
      const directorSigDataUrl = await loadAsset(directorSignature || undefined);
      const secSigDataUrl = await loadAsset(secSignature || undefined);

      // Setup PDF
      const isLandscape = docType === 'conclusao';
      const docPdf = new jsPDF({ orientation: isLandscape ? 'landscape' : 'portrait', unit: 'mm', format: 'a4' });
      const w = docPdf.internal.pageSize.getWidth();

      // --- PAGE 1 ---
      drawClassicBorder(docPdf);
      drawWatermark(docPdf, logoDataUrl);
      drawCleanHeader(docPdf, docTitle, logoDataUrl); // Logo on left, Title center

      // Content Logic
      const marginX = 20;
      let cursorY = 55; // Initial Y after header

      if (isLandscape) {
        // CERTIFICATE (Landscape) - Centralized Text
        docPdf.setFont("times", "normal");
        docPdf.setFontSize(16);
        docPdf.setTextColor(20, 20, 20);

        const certText = "Certificamos que";
        docPdf.text(certText, w/2, cursorY, { align: "center" });
        cursorY += 15;

        // Student Name (Big)
        docPdf.setFont("times", "bold");
        docPdf.setFontSize(28);
        docPdf.setTextColor(...PDF_THEME.textMain);
        docPdf.text(safeText(opStudent.displayName).toUpperCase(), w/2, cursorY, { align: "center" });
        cursorY += 15;

        // Body Text
        docPdf.setFont("times", "normal");
        docPdf.setFontSize(14);
        docPdf.setTextColor(40, 40, 40);
        const courseName = safeText(courseData.nome || opStudent.cursoInicial || 'TEOLOGIA').toUpperCase();
        const body = `Concluiu com êxito o curso de ${courseName}, cumprindo integralmente a carga horária e os requisitos acadêmicos previstos no projeto pedagógico desta instituição.`;
        const lines = docPdf.splitTextToSize(body, w - (marginX * 3));
        docPdf.text(lines, w/2, cursorY, { align: "center" });
        cursorY += (lines.length * 8) + 15;

        // Data Info (Centered Block)
        const dateStr = new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
        docPdf.setFontSize(11);
        docPdf.setTextColor(...PDF_THEME.textSec);
        docPdf.text(`CPF: ${safeText(opStudent.cpf)}   •   Matrícula: ${safeText(opStudent.academicId)}`, w/2, cursorY, { align: "center" });
        cursorY += 7;
        docPdf.text(`São Paulo, ${dateStr}`, w/2, cursorY, { align: "center" });

      } else {
        // DECLARATION / HISTORY (Portrait) - Justified Text

        // 1. Dados do Aluno (Clean Block)
        const courseName = safeText(courseData.nome || opStudent.cursoInicial || 'TEOLOGIA').toUpperCase();
        cursorY = drawStudentDataClean(docPdf, cursorY, opStudent, courseName);
        cursorY += 15; // Gap

        // 2. Declaration Text
        docPdf.setDrawColor(...PDF_THEME.lineColor);
        docPdf.line(marginX, cursorY, w - marginX, cursorY); // Separator
        cursorY += 10;

        docPdf.setFont("times", "bold");
        docPdf.setFontSize(12);
        docPdf.setTextColor(...PDF_THEME.textMain);
        docPdf.text("DECLARAÇÃO", marginX, cursorY);
        cursorY += 8;

        docPdf.setFont("times", "normal");
        docPdf.setFontSize(12);
        docPdf.setTextColor(20, 20, 20);

        let body = "";
        if (docType === 'matricula') {
          body = `Declaramos, para os devidos fins, que o(a) aluno(a) acima identificado(a) encontra-se regularmente MATRICULADO(A) no curso de ${courseName} desta instituição, frequentando as atividades acadêmicas do presente período letivo.`;
        } else if (docType === 'transferencia') {
          body = `Atestamos a transferência do(a) discente, vinculado(a) ao curso de ${courseName}, estando apto(a) a prosseguir seus estudos na instituição de destino, conforme legislação vigente.`;
        } else {
          body = `Certificamos o Histórico Escolar do(a) aluno(a), referente ao curso de ${courseName}, conforme detalhamento de disciplinas e notas apresentados em anexo ou na tabela a seguir.`;
        }

        const lines = docPdf.splitTextToSize(body, w - (marginX * 2));
        docPdf.text(lines, marginX, cursorY);
        cursorY += (lines.length * 6) + 15;

        const dateStr = new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
        docPdf.text(`São Paulo, ${dateStr}.`, w - marginX, cursorY, { align: "right" });
        cursorY += 20;

        // Tabela se for histórico (se couber na pág 1)
        if (docType === 'historico' && modulesData.length > 0) {
           autoTable(docPdf, {
            startY: cursorY,
            head: [["Disciplina / Módulo", "C.H.", "Situação"]],
            body: modulesData.map(m => [safeText(m.title), safeText(m.cargaHoraria||"20h"), "APROVADO"]),
            theme: "plain",
            styles: { fontSize: 9, cellPadding: 2 },
            headStyles: { fontStyle: "bold", fillColor: [240,240,240] },
            margin: { left: marginX, right: marginX }
           });
        }
      }

      // Footer (Safe Position)
      drawSecureFooter(docPdf, schoolName, validationUrl, code, qrCodeDataUrl, directorSigDataUrl, secSigDataUrl);

      // --- SAVE LOGIC ---
      const pdfBlob = docPdf.output('blob');
      const dataUri = docPdf.output('datauristring');
      const base64 = dataUriToBase64(dataUri);
      const localUrl = URL.createObjectURL(pdfBlob);
      window.open(localUrl, '_blank');

      const cleanTitle = safeName(`${docTitle}-${opStudent.displayName}.pdf`);
      const storagePath = `secretaria_docs/${opStudent.uid}/${code}-${cleanTitle}`;
      let uploadResult: any = { ok: false, url: "", storagePath: null, fallbackReason: "forced_base64" };
      try { uploadResult = await uploadBlobToStorage(pdfBlob, storagePath, 'application/pdf'); } catch(e) { uploadResult = {ok:false}; }

      const docRef = await addDoc(collection(db, 'secretaria_arquivos'), {
        name: `${docTitle} - ${opStudent.displayName}.pdf`,
        type: 'file', mimeType: 'application/pdf',
        url: FORCE_BASE64_URL ? dataUri : (uploadResult.ok ? uploadResult.url : dataUri),
        base64Chunked: false, storagePath: uploadResult.ok ? uploadResult.storagePath : null,
        studentId: opStudent.uid, docType: docType, createdAt: serverTimestamp(),
        docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId } }
      });

      if (base64.length > 900_000) {
        const chunks = splitIntoChunks(base64, 800_000);
        await updateDoc(doc(db, "secretaria_arquivos", docRef.id), { url: null, base64Chunked: true, chunksCount: chunks.length });
        for (let i = 0; i < chunks.length; i++) { await setDoc(doc(db, "secretaria_arquivos", docRef.id, "chunks", String(i)), { index: i, data: chunks[i] }); }
      }

    } catch (e: any) { alert("Erro: " + e.message); } 
    finally { setIsGeneratingPdf(false); }
  };

  // --- MISSING HANDLERS ---

  const handleStudentFinalize = async () => {
    if(!activeTicket) return;
    if(!confirm("Deseja encerrar este atendimento?")) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Finalizado', updatedAt: serverTimestamp() });
    setActiveTicket((prev: any) => prev ? {...prev, status: 'Finalizado'} : null);
  };

  const submitSurvey = async () => {
    if (!activeTicket) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Arquivado', archivedAt: serverTimestamp() });
    setActiveTicket(null);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
      text: chatMessage,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', activeTicket.id), {
      lastMessage: chatMessage,
      updatedAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeTicket) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
        if(ev.target?.result) {
            const base64 = ev.target.result as string;
            await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                text: `Arquivo enviado: ${file.name}`,
                attachmentUrl: base64,
                sender: 'Secretaria',
                createdAt: serverTimestamp()
            });
            await updateDoc(doc(db, 'tickets', activeTicket.id), {
                lastMessage: `[Arquivo]: ${file.name}`,
                updatedAt: serverTimestamp()
            });
        }
    };
    reader.readAsDataURL(file);
  };

  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const cleanName = safeName(file.name);
    const storagePath = `secretaria_files/${user.uid}/${Date.now()}-${cleanName}`;

    let uploadResult: any = { ok: false, url: "", storagePath: null };
    try {
        uploadResult = await uploadBlobToStorage(file, storagePath, file.type);
    } catch(e) {
        console.error("Upload failed", e);
    }

    let fileUrl = uploadResult.url;

    if (!uploadResult.ok) {
        const reader = new FileReader();
        fileUrl = await new Promise((resolve) => {
            reader.onload = (ev) => resolve(ev.target?.result as string);
            reader.readAsDataURL(file);
        });
    }

    const docRef = await addDoc(collection(db, 'secretaria_arquivos'), {
      name: file.name, 
      type: 'file', 
      mimeType: file.type, 
      url: fileUrl, 
      parentId: currentFolderId, 
      size: file.size, 
      createdAt: serverTimestamp(), 
      createdBy: user.uid,
      storagePath: uploadResult.storagePath,
      base64Chunked: false
    });

    if (!uploadResult.ok && fileUrl.length > 900_000) {
        const base64Data = dataUriToBase64(fileUrl);
        const chunks = splitIntoChunks(base64Data, 800_000);
        await updateDoc(doc(db, "secretaria_arquivos", docRef.id), { 
            url: null, 
            base64Chunked: true, 
            chunksCount: chunks.length 
        });
        for (let i = 0; i < chunks.length; i++) { 
            await setDoc(doc(db, "secretaria_arquivos", docRef.id, "chunks", String(i)), { index: i, data: chunks[i] }); 
        }
    }
  };

  const handleDeleteFile = async (id: string) => {
      if(confirm('Tem certeza que deseja excluir este item?')) {
          await deleteDoc(doc(db, 'secretaria_arquivos', id));
      }
  }

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId, updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false);
      setFileToMove(null);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- RENDER (KEEPING UI SAME) ---
  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>
      <main className="flex-1 overflow-hidden flex flex-col">
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-4 bg-slate-50 border-b flex gap-2">
                    {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => ( <button key={f} onClick={() => setTicketFilter(f)} className={`px-3 py-1 rounded text-[10px] font-black uppercase ${ticketFilter === f ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>{f}</button> ))}
                </div>
                <div className="flex-1 overflow-y-auto p-4">
                    {tickets.filter(t => ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter).map(t => (
                        <div key={t.id} className="flex justify-between p-3 border-b hover:bg-slate-50 items-center"><div><span className="font-bold text-xs text-indigo-700">#{t.protocolo}</span> <span className="text-xs ml-2 text-slate-700">{t.user}</span><div className="text-[10px] text-slate-400">{t.lastMessage}</div></div><button onClick={() => {setActiveTicket(t); setActiveTab('chat');}} className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded text-[10px] font-bold uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">Abrir</button></div>
                    ))}
                </div>
             </div>
         )}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative">
                {activeTicket ? (
                  <>
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><div><h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Status: {activeTicket.status}</p></div>{timerDisplay && <div className="flex items-center gap-2 px-3 py-1 bg-amber-50 text-amber-600 rounded-lg border border-amber-100 animate-pulse"><Clock size={12} /><span className="text-[10px] font-black uppercase">Espera: {timerDisplay}</span></div>}<div className="flex gap-2">{activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' && <button onClick={handleStudentFinalize} className="px-3 py-2 bg-rose-50 text-rose-600 rounded-lg text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all border border-rose-100">Encerrar</button>}</div></div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50 relative">
                       {messages.map((m, i) => ( <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' || m.sender === 'Sistema' ? 'items-end' : 'items-start'}`}><div className={`max-w-[75%] p-3 rounded-2xl text-xs font-medium leading-relaxed shadow-sm ${m.sender === 'Secretaria' ? 'bg-indigo-600 text-white rounded-br-none' : m.isBot ? 'bg-slate-200 text-slate-600 rounded-bl-none text-[11px]' : 'bg-white border border-slate-200 text-slate-700 rounded-bl-none'}`}>{m.text}</div><span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-1">{m.sender}</span></div> ))}
                       <div ref={chatEndRef} />
                    </div>
                    {/* Input Area */}
                    {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') ? (<div className="p-6 bg-slate-100 border-t flex flex-col items-center gap-4 text-center"><button onClick={submitSurvey} className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold uppercase text-xs shadow-lg hover:bg-indigo-700">Arquivar Ticket</button></div>) : activeTicket.status !== 'Arquivado' ? (<div className="p-4 border-t border-slate-100 bg-white"><div className="flex gap-3 items-center"><button onClick={() => chatFileInputRef.current?.click()} className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-indigo-100 hover:text-indigo-600 transition-all"><Paperclip size={18}/></button><input type="file" ref={chatFileInputRef} className="hidden" onChange={handleChatFileUpload}/><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-slate-50 border-none rounded-lg py-2 px-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Digite sua resposta..." /><button onClick={sendMessage} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-md transition-all"><Send size={18}/></button></div></div>) : <div className="p-4 text-center bg-slate-50 text-xs text-slate-400 uppercase font-bold">Ticket Arquivado</div>}
                  </>
                ) : (<div className="flex-1 flex flex-col items-center justify-center text-slate-300"><MessageSquare size={48} className="mb-4 opacity-20"/><p className="text-xs uppercase font-bold">Selecione um atendimento</p></div>)}
             </div>
         )}
         {activeTab === 'arquivos' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                 <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                     <div className="flex gap-1 items-center overflow-x-auto">{folderPath.map((folder, idx) => (<div key={folder.id} className="flex items-center"><button onClick={() => handleBreadcrumb(idx)} className="text-xs font-bold text-slate-600 hover:text-indigo-600 uppercase hover:underline">{folder.name}</button>{idx < folderPath.length - 1 && <ChevronRight size={12} className="mx-1 text-slate-300"/>}</div>))}</div>
                     <div className="flex gap-2"><button onClick={handleCreateFolder} className="p-2 bg-white border border-slate-200 rounded hover:bg-indigo-50 text-indigo-600"><FolderPlus size={16}/></button><button onClick={() => fileInputRef.current?.click()} className="p-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 shadow-sm"><UploadCloud size={16}/></button><input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} /></div>
                 </div>
                 <div className="flex-1 overflow-y-auto p-4"><div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">{currentItems.map(item => (<div key={item.id} className="group relative bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center justify-center gap-3 hover:shadow-md hover:border-indigo-200 transition-all cursor-pointer" onClick={() => item.type === 'folder' ? handleNavigate(item) : viewFile(item)}>{item.type === 'folder' ? <Folder size={32} className="text-indigo-400 group-hover:text-indigo-600"/> : <FileText size={32} className="text-slate-400 group-hover:text-slate-600"/>}<span className="text-[10px] font-bold uppercase text-center text-slate-600 truncate w-full">{item.name}</span><button onClick={(e) => { e.stopPropagation(); handleDeleteFile(item.id); }} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 p-1 text-rose-400 hover:bg-rose-50 rounded"><Trash2 size={12}/></button><button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="absolute top-1 left-1 opacity-0 group-hover:opacity-100 p-1 text-indigo-400 hover:bg-indigo-50 rounded"><Move size={12}/></button></div>))}</div></div>
             </div>
         )}
         {activeTab === 'operacional' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                 <div className="p-6 border-b border-slate-100 bg-slate-50"><h2 className="text-sm font-black uppercase text-slate-800 mb-4 flex items-center gap-2"><Printer size={16}/> Emissão de Documentos</h2><div className="flex gap-4"><div className="flex-1 relative"><Search className="absolute left-3 top-3 text-slate-400" size={16}/><input className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Buscar aluno por nome ou CPF..." value={studentSearchTerm} onChange={e => setStudentSearchTerm(e.target.value)} /></div></div></div>
                 <div className="flex-1 flex overflow-hidden">
                    <div className="w-1/3 border-r border-slate-100 overflow-y-auto bg-slate-50/50 p-2">{students.filter(s => s.displayName?.toLowerCase().includes(studentSearchTerm.toLowerCase()) || s.cpf?.includes(studentSearchTerm)).map(s => (<div key={s.uid} onClick={() => setOpStudent(s)} className={`p-3 mb-2 rounded-lg cursor-pointer border ${opStudent?.uid === s.uid ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'}`}><div className="font-bold text-xs uppercase">{s.displayName}</div><div className="text-[10px] opacity-70 flex justify-between mt-1"><span>CPF: {s.cpf || '---'}</span><span>{s.academicId}</span></div></div>))}</div>
                    <div className="flex-1 p-6 overflow-y-auto">{opStudent ? (<div className="space-y-6 animate-in fade-in slide-in-from-right-4"><div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100"><h3 className="font-black text-indigo-900 text-lg uppercase">{opStudent.displayName}</h3><div className="grid grid-cols-2 gap-4 mt-2 text-xs text-indigo-700"><p><strong>Email:</strong> {opStudent.email}</p><p><strong>Curso:</strong> {opStudent.cursoInicial || 'Não definido'}</p><p><strong>Status:</strong> <span className="px-2 py-0.5 bg-white rounded border border-indigo-200 uppercase font-bold text-[10px]">{opStudent.status || 'Pendente'}</span></p><button onClick={() => {setEditingStudent(opStudent); setAuditModalOpen(true);}} className="text-left underline hover:text-indigo-900">Editar Dados / Validar</button></div></div><div><h4 className="text-xs font-bold uppercase text-slate-400 mb-3 tracking-widest">Documentos Disponíveis</h4><div className="grid grid-cols-2 gap-4">{[{id: 'matricula', label: 'Declaração de Matrícula', icon: FileText},{id: 'historico', label: 'Histórico Escolar', icon: File},{id: 'conclusao', label: 'Certificado de Conclusão', icon: Award},{id: 'transferencia', label: 'Guia de Transferência', icon: ArrowRightLeft}].map((docItem) => (<button key={docItem.id} onClick={() => generateLegalPDF(docItem.id as any)} disabled={isGeneratingPdf} className="flex items-center gap-3 p-4 bg-white border border-slate-200 rounded-xl hover:border-indigo-500 hover:shadow-md transition-all group disabled:opacity-50"><div className="p-3 bg-slate-50 rounded-lg group-hover:bg-indigo-600 group-hover:text-white transition-colors"><docItem.icon size={20}/></div><div className="text-left"><div className="font-bold text-slate-700 text-xs uppercase group-hover:text-indigo-700">{docItem.label}</div><div className="text-[10px] text-slate-400">{isGeneratingPdf ? 'Gerando...' : 'Gerar PDF Assinado'}</div></div></button>))}</div></div></div>) : (<div className="h-full flex flex-col items-center justify-center text-slate-300"><Search size={48} className="mb-4 opacity-20"/><p className="text-xs uppercase font-bold">Selecione um aluno para iniciar</p></div>)}</div>
                 </div>
             </div>
         )}
      </main>

      {/* Modais */}
      {moveModalOpen && (<div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"><div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm"><h3 className="font-bold text-slate-800 mb-4">Mover para...</h3><div className="space-y-2 max-h-60 overflow-y-auto border p-2 rounded"><div onClick={() => setMoveTargetFolderId('root')} className={`p-2 rounded cursor-pointer ${moveTargetFolderId === 'root' ? 'bg-indigo-100 text-indigo-700' : 'hover:bg-slate-50'}`}><Folder size={14} className="inline mr-2"/> Raiz</div>{fileSystem.filter(f => f.type === 'folder' && f.id !== fileToMove?.id).map(f => (<div key={f.id} onClick={() => setMoveTargetFolderId(f.id)} className={`p-2 rounded cursor-pointer ${moveTargetFolderId === f.id ? 'bg-indigo-100 text-indigo-700' : 'hover:bg-slate-50'}`}><Folder size={14} className="inline mr-2"/> {f.name}</div>))}</div><div className="flex justify-end gap-2 mt-4"><button onClick={() => setMoveModalOpen(false)} className="px-4 py-2 text-xs font-bold text-slate-500">Cancelar</button><button onClick={handleMoveFile} className="px-4 py-2 bg-indigo-600 text-white rounded text-xs font-bold">Mover</button></div></div></div>)}
      {auditModalOpen && editingStudent && (<div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"><div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg"><h3 className="font-bold text-slate-800 mb-4 uppercase flex items-center gap-2"><ShieldCheck size={18}/> Auditoria de Cadastro</h3><div className="grid grid-cols-2 gap-4"><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome Completo</label><input className="w-full p-2 border rounded text-xs" value={editingStudent.displayName} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})}/></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">CPF</label><input className="w-full p-2 border rounded text-xs" value={editingStudent.cpf || ''} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})}/></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Matrícula (ID)</label><input className="w-full p-2 border rounded text-xs bg-slate-50" disabled value={editingStudent.academicId || ''}/></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Status Acadêmico</label><select className="w-full p-2 border rounded text-xs" value={editingStudent.status || 'pendente'} onChange={e => setEditingStudent({...editingStudent, status: e.target.value})}><option value="pendente">Pendente</option><option value="ativo">Ativo (Regular)</option><option value="bloqueado">Bloqueado</option><option value="formado">Formado</option></select></div></div><div className="mt-6 flex justify-end gap-2"><button onClick={() => setAuditModalOpen(false)} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded">Cancelar</button><button onClick={async () => { try { await updateDoc(doc(db, 'users', editingStudent.uid), editingStudent); alert("Dados atualizados!"); setAuditModalOpen(false); } catch(e) { alert("Erro ao salvar."); } }} className="px-4 py-2 bg-indigo-600 text-white rounded text-xs font-bold hover:bg-indigo-700">Salvar Alterações</button></div></div></div>)}
    </div>
  );
};

export default SecretariatView;
